### Description
This Terraform program configures a Route 53 zone named "primary" and sets up a query log that writes to a CloudWatch log group named "aws_route53_example_com". It creates an IAM role and policy that allow Route 53 to write to the CloudWatch log group. The program ensures that all dependencies are correctly handled, and it uses realistic offline-valid AWS values.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "/aws/route53/example.com"
}

resource "aws_iam_role" "route53_query_logging_role" {
  name = "route53-query-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "route53_query_logging_policy" {
  name = "route53-query-logging-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = aws_cloudwatch_log_group.aws_route53_example_com.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_route53_query_logging_policy" {
  policy_arn = aws_iam_policy.route53_query_logging_policy.arn
  role       = aws_iam_role.route53_query_logging_role.name
}

resource "aws_route53_query_log" "route53_query_log" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id                  = aws_route53_zone.primary.zone_id
}
```

This Terraform configuration sets up the necessary AWS resources to enable Route 53 query logging to a CloudWatch log group. It includes the creation of a Route 53 zone, a CloudWatch log group, an IAM role with the appropriate trust relationship, an IAM policy allowing Route 53 to write to the log group, and the attachment of the policy to the role. Finally, it creates the Route 53 query log resource that ties everything together.

