### Description
This Terraform program sets up a weighted routing policy using Amazon Route 53 to distribute traffic between a primary database instance and three replica database instances located in different AWS regions. The primary database instance is provisioned in "us-west-1", while the replicas are provisioned in "us-east-1", "eu-central-1", and "ap-southeast-1". A Route 53 zone named "main" is created in "us-west-1" to manage the DNS records.

### Terraform HCL Program

```hcl
provider "aws" {
  alias  = "main"
  region = "us-west-1"
}

provider "aws" {
  alias  = "us-east"
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-central"
  region = "eu-central-1"
}

provider "aws" {
  alias  = "ap-southeast"
  region = "ap-southeast-1"
}

resource "aws_route53_zone" "main" {
  name = "main.example.com"
}

resource "aws_db_instance" "primary" {
  provider         = aws.main
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  engine           = "mysql"
  username         = "admin"
  password         = "password"
}

resource "aws_db_instance" "replica_us_east" {
  provider         = aws.us-east
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  engine           = "mysql"
  username         = "admin"
  password         = "password"
  replicate_source_db = aws_db_instance.primary.identifier
}

resource "aws_db_instance" "replica_eu_central" {
  provider         = aws.eu-central
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  engine           = "mysql"
  username         = "admin"
  password         = "password"
  replicate_source_db = aws_db_instance.primary.identifier
}

resource "aws_db_instance" "replica_ap_southeast" {
  provider         = aws.ap-southeast
  instance_class   = "db.t3.micro"
  allocated_storage = 20
  engine           = "mysql"
  username         = "admin"
  password         = "password"
  replicate_source_db = aws_db_instance.primary.identifier
}

resource "aws_route53_record" "weighted_routing_policy" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.main.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 100
  }

  records = [aws_db_instance.primary.endpoint]

  set_identifier = "primary"

  lifecycle {
    ignore_changes = [records]
  }
}

resource "aws_route53_record" "weighted_routing_policy_replica_us_east" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.main.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 30
  }

  records = [aws_db_instance.replica_us_east.endpoint]

  set_identifier = "replica_us_east"

  lifecycle {
    ignore_changes = [records]
  }
}

resource "aws_route53_record" "weighted_routing_policy_replica_eu_central" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.main.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 30
  }

  records = [aws_db_instance.replica_eu_central.endpoint]

  set_identifier = "replica_eu_central"

  lifecycle {
    ignore_changes = [records]
  }
}

resource "aws_route53_record" "weighted_routing_policy_replica_ap_southeast" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "db.main.example.com"
  type    = "A"

  weighted_routing_policy {
    weight = 30
  }

  records = [aws_db_instance.replica_ap_southeast.endpoint]

  set_identifier = "replica_ap_southeast"

  lifecycle {
    ignore_changes = [records]
  }
}
```

This Terraform configuration creates the necessary resources and sets up the weighted routing policy to distribute traffic between the primary and replica database instances. The primary instance is in "us-west-1", and the replicas are in "us-east-1", "eu-central-1", and "ap-southeast-1". The Route 53 zone "main" is also created in "us-west-1".

