  engine = "mysql"
  username = "admin"
  password = "password"
  db_name = "mydatabase"
  replicate_source_db = aws_db_instance.primary_db_instance.identifier
}

resource "aws_db_instance" "replica_2_db_instance" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "mysql"
  username = "admin"
  password = "password"
  db_name = "mydatabase"
  replicate_source_db = aws_db_instance.primary_db_instance.identifier
}

resource "aws_route53_record" "weighted_record_primary" {
  name    = "db"
  type    = "A"
  zone_id = aws_route53_zone.main_zone.zone_id
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  records = [aws_db_instance.primary_db_instance.endpoint]
}

resource "aws_route53_record" "weighted_record_replica_1" {
  name    = "db"
  type    = "A"
  zone_id = aws_route53_zone.main_zone.zone_id
  ttl     = 300

  weighted_routing_policy {
