Below is a complete Terraform HCL program that configures Route 53 resources to manage a domain and directs traffic to an Elastic Beanstalk environment. The program includes the necessary IAM roles, S3 bucket, and Elastic Beanstalk resources, ensuring all dependencies are preserved.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_s3_bucket" "unique_bucket_name" {
  bucket = "unique-bucket-name-${random_string.suffix.result}"
  acl    = "private"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.unique_bucket_name.bucket
  key    = "example-object.txt"
  content = "This is an example object."
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.unique_bucket_name.bucket
  key         = aws_s3_object.examplebucket_object.key
  name        = "version"
}

resource "aws_elastic_beanstalk_environment" "eb_env" {
  application = aws_elastic_beanstalk_application.myapp.name
  name        = "eb-env"
  version_label = aws_elastic_beanstalk_application_version.version.name
}

resource "aws_route53_zone" "main" {
  name = "example.com"
}

resource "aws_route53_record" "main_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.example.com"
  type    = "CNAME"
  ttl     = 300

  alias {
    name                   = aws_elastic_beanstalk_environment.eb_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eb_env.cname_suffix
    evaluate_target_health = true
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role and Instance Profile**: An IAM role (`eb_ec2_role`) and an instance profile (`eb_ec2_profile`) are created for EC2 instances in the Elastic Beanstalk environment.
3. **S3 Bucket and Object**: A unique S3 bucket (`unique_bucket_name`) and an object (`examplebucket_object`) are created to store application code.
4. **Elastic Beanstalk Application and Version**: An Elastic Beanstalk application (`myapp`) and its version (`version`) are defined, linked to the S3 object.
5. **Elastic Beanstalk Environment**: An Elastic Beanstalk environment (`eb_env`) is created using the application and version.
6. **Route 53 Zone and Record**: A Route 53 hosted zone (`main`) and a record (`main_record`) are created to direct traffic to the Elastic Beanstalk environment using a CNAME record.

