### Description
This Terraform program sets up a Blue/Green deployment using AWS Elastic Beanstalk environments and AWS Route53 for traffic management. The program creates two Elastic Beanstalk environments named "blue" and "green" and configures Route53 with weighted routing to distribute traffic between these environments. An IAM role and policy are created to allow Route53 updates.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Route53 updates
resource "aws_iam_role" "route53_update_role" {
  name = "route53-update-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Route53 updates
resource "aws_iam_policy" "route53_update_policy" {
  name        = "route53-update-policy"
  description = "Policy to allow Route53 updates"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "route53:ChangeResourceRecordSets",
          "route53:GetHostedZone",
          "route53:ListResourceRecordSets"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_route53_policy_to_role" {
  policy_arn = aws_iam_policy.route53_update_policy.arn
  role       = aws_iam_role.route53_update_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_app" {
  name        = "my-app"
  description = "My Elastic Beanstalk Application"
}

# Blue Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "blue_environment" {
  name                = "blue-environment"
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
}

# Green Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "green_environment" {
  name                = "green-environment"
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
}

# Route53 Hosted Zone
resource "aws_route53_zone" "primary_dns_zone" {
  name = "example.com"
}

# Weighted Record for Blue Environment
resource "aws_route53_record" "weighted_blue_record" {
  zone_id = aws_route53_zone.primary_dns_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  records = [aws_elastic_beanstalk_environment.blue_environment.endpoint_url]
}

# Weighted Record for Green Environment
resource "aws_route53_record" "weighted_green_record" {
  zone_id = aws_route53_zone.primary_dns_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  records = [aws_elastic_beanstalk_environment.green_environment.endpoint_url]
}
```

This Terraform configuration sets up the necessary resources for a Blue/Green deployment using AWS Elastic Beanstalk and Route53. It includes IAM roles and policies to manage Route53 updates, Elastic Beanstalk environments, and Route53 records with weighted routing.

