Below is a complete Terraform HCL program that configures a blue/green deployment with Route 53 resources to direct traffic to two separate environments connected to a shared RDS database. The program includes IAM roles, an RDS instance, a Route 53 zone, and DNS records with health checks and a failover routing policy.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_rds_instance" "myapp_db" {
  identifier              = "myapp-db"
  instance_class          = "db.t3.micro"
  engine                  = "mysql"
  engine_version          = "8.0"
  username                = "admin"
  password                = "password"
  allocated_storage       = 20
  skip_final_snapshot     = true
  db_subnet_group_name    = "default"
  vpc_security_group_ids  = ["sg-0123456789abcdef0"]
}

resource "aws_route53_zone" "myapp_zone" {
  name = "myapp.example.com"
}

resource "aws_route53_record" "blue_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "blue.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.1"]  # Replace with actual IP address
}

resource "aws_route53_record" "green_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "green.myapp.example.com"
  type    = "A"
  ttl     = 300
  records = ["192.168.1.2"]  # Replace with actual IP address
}

resource "aws_route53_health_check" "blue_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = aws_route53_record.blue_record.name
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_health_check" "green_health_check" {
  type                = "HTTP"
  fully_qualified_domain_name = aws_route53_record.green_record.name
  port                = 80
  resource_path       = "/"
  failure_threshold   = 3
  request_interval    = 30
}

resource "aws_route53_record" "failover_record" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.example.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue_health_check.id

  records = ["192.168.1.1"]  # Replace with actual IP address
}

resource "aws_route53_record" "failover_record_secondary" {
  zone_id = aws_route53_zone.myapp_zone.zone_id
  name    = "myapp.example.com"
  type    = "A"
  ttl     = 300

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.green_health_check.id

  records = ["192.168.1.2"]  # Replace with actual IP address
}
