### Description
This Terraform program provisions an infrastructure to deploy and scale a web application using AWS services. It includes an IAM role and instance profile, a security group, a launch template, and an Auto Scaling Group. The IAM role grants necessary permissions, the security group controls inbound and outbound traffic, the launch template defines the configuration for EC2 instances, and the Auto Scaling Group manages the deployment and scaling of the web application.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "web_app_role" {
  name = "web_app_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "web_app_instance_profile" {
  name = "web_app_instance_profile"
  role = aws_iam_role.web_app_role.name
}

resource "aws_security_group" "web_app_sg" {
  name        = "web_app_sg"
  description = "Security group for web application"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_launch_template" "web_app_lt" {
  name = "web_app_lt"

  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.web_app_instance_profile.name
  }

  security_group_names = [aws_security_group.web_app_sg.name]
}

resource "aws_autoscaling_group" "web_app_asg" {
  name                 = "web_app_asg"
  launch_template      = { id = aws_launch_template.web_app_lt.id, version = "$Latest" }
  min_size             = 1
  max_size             = 3
  desired_capacity     = 2
  vpc_zone_identifier  = ["subnet-0123456789abcdef0"]  # Example subnet ID
  health_check_type    = "ELB"
  health_check_grace_period = 300
}
```

### Notes
- The IAM role `web_app_role` is created with a basic trust policy allowing EC2 to assume the role.
- The instance profile `web_app_instance_profile` attaches the IAM role to EC2 instances.
- The security group `web_app_sg` allows HTTP (port 80) and HTTPS (port 443) traffic from any IP address.
- The launch template `web_app_lt` specifies the AMI ID, instance type, IAM instance profile, and security group.
- The Auto Scaling Group `web_app_asg` manages the deployment and scaling of the web application, with a minimum of 1 instance, a maximum of 3 instances, and a desired capacity of 2 instances.

