### Description
This Terraform program creates an AWS Lex bot for ordering pizza with a follow-up question. It includes the necessary IAM roles, policies, slot types, intents, and the main Lex bot. The bot will prompt users to select a pizza size and topping, and then confirm their order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy for Lex bot to interact with other AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "attach_lex_bot_policy" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

# Slot Type for Pizza Size
resource "aws_lex_slot_type" "pizza_size_slot_type" {
  name = "PizzaSize"

  enumeration_value {
    value = "Small"
  }

  enumeration_value {
    value = "Medium"
  }

  enumeration_value {
    value = "Large"
  }
}

# Slot Type for Pizza Topping
resource "aws_lex_slot_type" "pizza_topping_slot_type" {
  name = "PizzaTopping"

  enumeration_value {
    value = "Pepperoni"
  }

  enumeration_value {
    value = "Mushrooms"
  }

  enumeration_value {
    value = "Onions"
  }
}

# Intent for Ordering Pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name = "OrderPizza"

  slot {
    name            = "PizzaSize"
    slot_constraint = "Required"
    slot_type       = aws_lex_slot_type.pizza_size_slot_type.name
  }

  slot {
    name            = "PizzaTopping"
    slot_constraint = "Required"
    slot_type       = aws_lex_slot_type.pizza_topping_slot_type.name
  }

  sample_utterances = [
    "I want to order a pizza",
    "Can I order a pizza?",
    "Order me a pizza"
  ]

  confirmation_prompt {
    max_attempts = 2
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

# Main Lex Bot for Ordering Pizza
resource "aws_lex_bot" "pizza_ordering_bot" {
  name                = "PizzaOrderingBot"
  child_directed      = false
  locale              = "en-US"
  process_behavior    = "BUILD"
  voice_id            = "Joanna"
  idle_session_ttl_in_seconds = 300

  intent {
    intent_name     = aws_lex_intent.order_pizza_intent.name
    intent_version  = "$LATEST"
  }

  clarification_prompt {
    max_attempts = 2
  }
}
```

