### Description
This Terraform program creates an AWS Connect instance, an IAM role with a policy for SAML authentication, and associates a bot with the Connect instance using the SAML IAM role. The program ensures that all dependencies are correctly handled, and all required attributes are specified.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_connect_instance" "connect_instance" {
  identity_management_type = "SAML"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  instance_alias           = "my-connect-instance"
}

resource "aws_iam_role" "connect_saml_role" {
  name = "connect-saml-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithSAML"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "SAML:aud" = "https://signin.aws.amazon.com/saml"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "connect_saml_role_policy" {
  name = "connect-saml-policy"
  role = aws_iam_role.connect_saml_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "connect:GetFederationToken",
          "connect:ListApprovedOrigins",
          "connect:ListTagsForResource",
          "connect:TagResource",
          "connect:UntagResource"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_connect_bot_association" "connect_bot_association" {
  instance_id = aws_connect_instance.connect_instance.id

  lex_bot {
    name = "my-lex-bot"
  }
}
```

This Terraform configuration sets up an AWS Connect instance with SAML identity management, creates an IAM role with the necessary permissions for SAML authentication, and associates a Lex bot with the Connect instance. All dependencies are correctly handled, ensuring that the resources are created in the correct order.

