### Description
This Terraform program creates a Kinesis Firehose Delivery Stream with an extended S3 Destination, enabling dynamic partitioning. The program includes the necessary IAM roles and policies to allow the Firehose delivery stream to access the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_s3_access_policy" {
  name        = "firehose-s3-access-policy"
  description = "Policy granting S3 access permissions to the Firehose delivery stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::my-kinesis-firehose-bucket",
          "arn:aws:s3:::my-kinesis-firehose-bucket/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_s3_policy" {
  policy_arn = aws_iam_policy.firehose_s3_access_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn         = aws_iam_role.firehose_delivery_stream_role.arn
    bucket_arn       = "arn:aws:s3:::my-kinesis-firehose-bucket"
    prefix           = "data/"
    buffering_interval = 300
    buffering_size     = 5
    compression_format = "GZIP"
    dynamic_partitioning_configuration {
      enabled = true
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `firehose-delivery-stream-role` is created with a trust policy allowing Firehose to assume the role.
3. **IAM Policy**: An IAM policy named `firehose-s3-access-policy` is created to grant the necessary S3 permissions to the Firehose delivery stream.
4. **IAM Role Policy Attachment**: The policy is attached to the IAM role.
5. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream is created with an extended S3 destination. Dynamic partitioning is enabled, and the stream is configured to buffer data for 300 seconds or 5 MB before writing to S3.

