    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kinesis Firehose to access Elasticsearch
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose-delivery-stream-policy"
  description = "Policy for Kinesis Firehose to access Elasticsearch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:ESHttpPut",
          "es:ESHttpGet"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain/*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# Kinesis Firehose Delivery Stream with Elasticsearch Destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name = "my-kinesis-firehose-delivery-stream"

  elasticsearch_configuration {
    domain_arn         = "arn:aws:es:us-west-2:123456789012:domain/my-elasticsearch-domain"
    index_name         = "my-index"
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    type_name          = "my-type"
    buffering_interval = 300
    buffering_size     = 5
    retry_duration     = 300
    s3_backup_mode     = "Failed"
  }
}
```

### Notes
- Ensure that the Elasticsearch domain ARN (`domain_arn`) is correctly set to your existing Elasticsearch domain.
- The IAM policy grants permissions for `es:ESHttpPut` and `es:ESHttpGet` actions on the specified Elasticsearch domain.
- The Kinesis Firehose Delivery Stream is configured to buffer data for 300 seconds or 5 MB before sending it to Elasticsearch, with a retry duration of 300 seconds if the delivery fails.

