```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kinesis Firehose
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose-delivery-stream-policy"
  description = "Policy for Kinesis Firehose to deliver data to OpenSearch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet",
          "es:ESHttpDelete",
          "es:ESHttpHead",
          "es:ESHttpPatch"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

# VPC for Kinesis Firehose
resource "aws_vpc" "kinesis_firehose_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Subnet within the VPC
resource "aws_subnet" "kinesis_firehose_subnet" {
  vpc_id            = aws_vpc.kinesis_firehose_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Security Group for Kinesis Firehose
resource "aws_security_group" "kinesis_firehose_sg" {
  vpc_id = aws_vpc.kinesis_firehose_vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Kinesis Firehose Delivery Stream with OpenSearch Destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "kinesis-firehose-delivery-stream"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn         = "arn:aws:es:us-west-2:123456789012:domain/my-opensearch-domain"
    index_name         = "my-index"
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    buffering_interval = 300
    buffering_size     = 5
    retry_duration     = 300
    s3_backup_mode     = "Failed"
  }

  vpc_config {
    subnet_ids         = [aws_subnet.kinesis_firehose_subnet.id]
    security_group_ids = [aws_security_group.kinesis_firehose_sg.id]
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
  }
}
```

