### Description
This Terraform program creates a Kinesis Firehose Delivery Stream with an extended S3 Destination. It includes the necessary IAM roles and policies to allow the Firehose delivery stream to write to an S3 bucket. The program ensures that all dependencies are correctly handled, and it uses default values where appropriate.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_s3_access_policy" {
  name        = "firehose-s3-access-policy"
  description = "Policy granting S3 access permissions to the Firehose delivery stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::my-firehose-bucket",
          "arn:aws:s3:::my-firehose-bucket/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_s3_policy" {
  policy_arn = aws_iam_policy.firehose_s3_access_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

resource "aws_kinesis_firehose_delivery_stream" "extended_s3_delivery_stream" {
  name = "extended-s3-delivery-stream"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    bucket_arn = "arn:aws:s3:::my-firehose-bucket"
    prefix     = "firehose/"
    buffering_interval = 300
    buffering_size = 5
    compression_format = "GZIP"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `firehose-delivery-stream-role` is created with a trust policy allowing Firehose to assume the role.
