This Terraform program creates an Amazon Kendra data source with a proxy configuration. It includes the necessary IAM role and policy to allow Kendra to access the data source. The program ensures that all required attributes are specified and that dependencies between resources are correctly handled.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_data_source_role" {
  name = "kendra-data-source-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kendra_data_source_policy" {
  name = "kendra-data-source-policy"
  role = aws_iam_role.kendra_data_source_role.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::example-bucket",
          "arn:aws:s3:::example-bucket/*"
        ]
      }
    ]
  })
}

resource "aws_kendra_data_source" "kendra_data_source_with_proxy" {
  index_id = "example-index-id"
  name     = "kendra-data-source-with-proxy"
  type     = "S3"

  role_arn = aws_iam_role.kendra_data_source_role.arn

  configuration {
    s3_configuration {
      bucket_name = "example-bucket"
      inclusion_prefixes = ["documents/"]
      exclusion_patterns = []

      access_control_list_configuration {
        key_path = "acl.txt"
      }

      documents_metadata_configuration {
        s3_prefix = "metadata/"
      }

      proxy_configuration {
        host = "proxy.example.com"
        port = 8080
      }
    }
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `kendra-data-source-role` is created with a trust policy allowing Kendra to assume the role.
- **IAM Role Policy**: A policy is attached to the IAM role that grants Kendra permissions to access an S3 bucket (`example-bucket`).
- **Kendra Data Source**: A Kendra data source is created with the type `S3`. It uses the IAM role created earlier and includes a proxy configuration with a specified host and port. The S3 configuration specifies the bucket name, inclusion prefixes, and other settings.

