### Description
This Terraform program creates an Amazon Kendra index with user group resolution enabled. It includes the necessary IAM role and policy to allow Kendra to resolve user groups. The program ensures that all dependencies are correctly handled, and it uses realistic default values where necessary.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_user_group_resolution_role" {
  name = "kendra-user-group-resolution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kendra_user_group_resolution_policy" {
  name        = "kendra-user-group-resolution-policy"
  description = "Policy for Kendra to resolve user groups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ds:DescribeDirectories",
          "ds:GetDirectoryDetails",
          "ds:ListUsers",
          "ds:ListGroups",
          "ds:ListGroupMemberships"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kendra_policy_to_role" {
  policy_arn = aws_iam_policy.kendra_user_group_resolution_policy.arn
  role       = aws_iam_role.kendra_user_group_resolution_role.name
}

resource "aws_kendra_index" "kendra_index" {
  name            = "my-kendra-index"
  role_arn        = aws_iam_role.kendra_user_group_resolution_role.arn
  user_context_policy = "ATTRIBUTE_FILTER"

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }

  capacity_units {
    query_capacity_units   = 2
    storage_capacity_units = 50
  }
}
```

This Terraform configuration sets up an AWS Kendra index with user group resolution enabled using AWS Single Sign-On (SSO). It includes an IAM role and policy that grant Kendra the necessary permissions to resolve user groups. The Kendra index is configured with basic capacity units and a user context policy.

