provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "example_iam_role" {
  name = "example-eks-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example_iam_role_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.example_iam_role.name
}

resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.example_iam_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  }
}

resource "aws_eks_identity_provider_config" "example_eks_identity_provider_config" {
  cluster_name = aws_eks_cluster.example_eks_cluster.name

  oidc {
    client_id               = "example-client-id"
    identity_provider_config_name = "example-oidc-config"
    issuer_url              = "https://example.com"
    groups_claim            = "groups"
    groups_prefix           = "eks:"
    username_claim          = "sub"
    username_prefix         = "eks:"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `example-eks-role` is created with a trust policy allowing EKS to assume the role.
3. **IAM Role Policy Attachment**: The `AmazonEKSClusterPolicy` policy is attached to the IAM role to grant it necessary permissions to interact with EKS.
4. **EKS Cluster**: An EKS cluster named `example` is created with the IAM role ARN and VPC configuration.
5. **EKS Identity Provider Config**: An identity provider configuration is set up for the EKS cluster, specifying the OIDC provider details, including the client ID, issuer URL, and claims for groups and usernames.

