  client_id_list = ["sts.amazonaws.com"]
  url            = "https://oidc.eks.us-west-2.amazonaws.com/id/EXAMPLE1234567890"
}

resource "aws_eks_identity_provider_config" "example_eks_identity_provider_config" {
  cluster_name = aws_eks_cluster.example_eks_cluster.name

  oidc {
    client_id                = "sts.amazonaws.com"
    identity_provider_config_name = "example-oidc-config"
    issuer_url               = "https://oidc.eks.us-west-2.amazonaws.com/id/EXAMPLE1234567890"
