### Description
This Terraform script creates an AWS EKS node group named "example" linked to a specific EKS cluster also named "example". The node group is configured with scaling parameters and dependencies on IAM role policy attachments to ensure proper permissions management. The script includes the necessary IAM roles and policy attachments for the EKS worker node, EKS CNI, and EC2 container registry read-only policies.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "eks_node_group_role" {
  name = "eks-node-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

resource "aws_iam_role_policy_attachment" "attach_eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSCNIPolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

resource "aws_iam_role_policy_attachment" "attach_ec2_container_registry_read_only_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node_group_role.name
}

resource "aws_eks_cluster" "example_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_node_group_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  }
}

resource "aws_eks_node_group" "example_node_group" {
  cluster_name    = aws_eks_cluster.example_cluster.name
  node_role_arn   = aws_iam_role.eks_node_group_role.arn
  subnet_ids      = aws_eks_cluster.example_cluster.vpc_config[0].subnet_ids
  node_group_name = "example"

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }
}
```

### Notes
- Ensure that the subnet IDs provided in the `vpc_config` block are valid and exist in your AWS account.
- The IAM policies (AmazonEKSWorkerNodePolicy, AmazonEKSCNIPolicy, and AmazonEC2ContainerRegistryReadOnly) are standard AWS-managed policies and should be available in your account.
- The region specified in the provider configuration (`us-west-2`) can be changed to any valid AWS region as needed.

