### Description
This Terraform script sets up an AWS EKS cluster with pod identity management. It defines an IAM policy document for assuming a role by EKS pods, creates an IAM role using this policy, attaches a policy for S3 read-only access to this role, and finally defines an EKS pod identity association linking the role to a specific EKS cluster, namespace, and service account.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# Define the policy document for the IAM role to assume a role by EKS pods
data "aws_iam_policy_document" "example_assume_role_policy" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

# Create an IAM role using the defined policy document
resource "aws_iam_role" "example" {
  name               = "example"
  assume_role_policy = data.aws_iam_policy_document.example_assume_role_policy.json
}

# Attach a policy for S3 read-only access to the IAM role
resource "aws_iam_role_policy_attachment" "example_s3_read_only" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.example.name
}

# Define an EKS pod identity association linking the role to a specific EKS cluster, namespace, and service account
resource "aws_eks_pod_identity_association" "example_pod_identity" {
  cluster_name   = "example-cluster"
  namespace      = "default"
  role_arn       = aws_iam_role.example.arn
  service_account = "example-service-account"
}
```

### Notes
- Ensure that the EKS cluster named "example-cluster", the namespace "default", and the service account "example-service-account" are already created and configured in your AWS environment.
- The IAM policy document for S3 read-only access is attached using the predefined AWS-managed policy `AmazonS3ReadOnlyAccess`.

