### Description
This Terraform program creates an AWS S3 bucket named 'wellcomecollection-platform-infra' with preventive destruction measures. The bucket is configured with a private ACL, versioning, and a lifecycle policy. The lifecycle policy includes automatic deletion of objects with a 'tmp/' prefix after 30 days, transitioning old versions to the 'STANDARD_IA' storage class after 30 days, and deleting noncurrent versions after 90 days.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_s3_bucket" "wellcomecollection_platform_infra" {
  bucket        = "wellcomecollection-platform-infra"
  acl           = "private"
  force_destroy = false  # Preventive destruction measure

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket_acl" "wellcomecollection_platform_infra_acl" {
  bucket = aws_s3_bucket.wellcomecollection_platform_infra.id
  acl    = "private"
}

resource "aws_s3_bucket_lifecycle_configuration" "wellcomecollection_platform_infra_lifecycle" {
  bucket = aws_s3_bucket.wellcomecollection_platform_infra.id

  rule {
    id     = "DeleteTmpObjects"
    status = "Enabled"

    filter {
      prefix = "tmp/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "TransitionOldVersions"
    status = "Enabled"

    filter {
      prefix = ""
    }

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }
  }

  rule {
    id     = "DeleteNoncurrentVersions"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}
```

This Terraform configuration sets up the S3 bucket with the specified requirements, ensuring that all dependencies are correctly handled and that the bucket is protected from accidental deletion.

