### Description
This Terraform program defines a Virtual Private Cloud (VPC) with both public and private subnets. It also sets up an EC2 Fleet consisting of 5 On-Demand and 4 Spot instances using the latest Amazon Linux 2 AMI. The configuration uses Launch Templates for consistency and includes necessary IAM roles and instance profiles.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false
  availability_zone       = "us-west-2b"
  tags = {
    Name = "PrivateSubnet"
  }
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "EC2FleetRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "EC2FleetInstanceProfile"
  role = aws_iam_role.ec2_fleet_role.name
}

resource "aws_launch_template" "ec2_fleet_launch_template" {
  name = "EC2FleetLaunchTemplate"

  image_id               = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type          = "t3.micro"
  key_name               = "my-key-pair"            # Replace with your key pair name
  iam_instance_profile   = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  vpc_security_group_ids = ["sg-0123456789abcdef0"] # Replace with your security group ID

  tags = {
    Name = "EC2FleetLaunchTemplate"
  }
}

resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template {
      id      = aws_launch_template.ec2_fleet_launch_template.id
      version = "$Latest"
    }
  }

  target_capacity_specification {
    total_target_capacity     = 9
    default_target_capacity_type = "spot"
    spot_target_capacity      = 4
    on_demand_target_capacity = 5
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  tags = {
    Name = "MainEC2Fleet"
  }
}
```

### Notes
- Ensure that the `key_name` and `vpc_security_group_ids` in the `aws_launch_template` resource are replaced with your actual key pair name and security group ID.
- The `image_id` for Amazon Linux 2 may vary based on your region and the latest available AMI. You can find the correct AMI ID using the AWS Management Console or AWS CLI.
- The `availability_zone` values for the subnets should match the availability zones available in your chosen region. Adjust them accordingly if needed.

