### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasti_cache_user_role" {
  name = "elasti_cache_user_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "elasti_cache_user_policy" {
  name        = "elasti_cache_user_policy"
  description = "Policy for ElastiCache user operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:Describe*",
          "elasticache:List*",
          "elasticache:Modify*",
          "elasticache:Reboot*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elasti_cache_user_policy" {
  policy_arn = aws_iam_policy.elasti_cache_user_policy.arn
  role       = aws_iam_role.elasti_cache_user_role.name
}

resource "aws_elasticache_user" "elasti_cache_user" {
  user_id     = "my_elasti_cache_user"
  user_name   = "my_elasti_cache_user"
  access_string = "on ~app::* -@allusers"
  engine      = "redis"
  passwords   = ["MySecurePassword123"]

  depends_on = [aws_iam_role_policy_attachment.attach_elasti_cache_user_policy]
}
```

