### Description
This Terraform program sets up a primary RedShift cluster in the `us-east-1` region and a replica RedShift cluster in the `us-east-2` region. It also creates an IAM role and policy necessary for the replication process. The replica cluster depends on the primary cluster, and the IAM role is attached with the appropriate policy.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_redshift_cluster" "redshift_cluster_us_east_1" {
  cluster_identifier = "primary-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  database_name      = "mydatabase"
  cluster_type       = "single-node"
  automated_snapshot_retention_period = 7
  allow_version_upgrade = true
  apply_immediately   = true

  logging {
    enable      = true
    bucket_name = "redshift-logs-us-east-1"
    log_exports = ["connectionlog", "userlog", "useractivitylog"]
  }
}

provider "aws" {
  alias  = "us-east-2"
  region = "us-east-2"
}

resource "aws_redshift_cluster" "redshift_cluster_us_east_2" {
  provider = aws.us-east-2

  cluster_identifier = "replica-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  database_name      = "mydatabase"
  cluster_type       = "single-node"
  automated_snapshot_retention_period = 7
  allow_version_upgrade = true
  apply_immediately   = true

  snapshot_copy {
    destination_region = "us-east-2"
  }

  depends_on = [aws_redshift_cluster.redshift_cluster_us_east_1]
}

resource "aws_iam_role" "redshift_replication_role" {
  name = "redshift-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_replication_policy" {
  name        = "redshift-replication-policy"
  description = "Policy for RedShift replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeRouteTables",
          "kms:DescribeKey",
          "kms:GetKeyPolicy",
          "kms:ListAliases",
          "kms:ListGrants",
          "kms:ListKeys",
          "kms:ListKeyPolicies"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_redshift_replication_policy_to_role" {
  policy_arn = aws_iam_policy.redshift_replication_policy.arn
  role       = aws_iam_role.redshift_replication_role.name

  depends_on = [
    aws_iam_role.redshift_replication_role,
    aws_iam_policy.redshift_replication_policy
  ]
}
```

This Terraform configuration sets up the primary RedShift cluster in `us-east-1`, the replica cluster in `us-east-2`, and the necessary IAM role and policy for replication. The replica cluster depends on the primary cluster, ensuring that the replication setup is correctly configured.

