### Description
This Terraform program creates a 2-node Amazon Redshift cluster and attaches a resource policy to it. The program includes the necessary IAM roles and policies to ensure proper access and permissions for the Redshift cluster. The Redshift clusters are created as separate resources but are part of the same cluster configuration.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Redshift Cluster
resource "aws_iam_role" "redshift_cluster_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift Cluster
resource "aws_iam_policy" "redshift_cluster_policy" {
  name        = "redshift-cluster-policy"
  description = "Policy for Redshift Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::my-redshift-bucket",
          "arn:aws:s3:::my-redshift-bucket/*"
        ]
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_policy_to_role" {
  policy_arn = aws_iam_policy.redshift_cluster_policy.arn
  role       = aws_iam_role.redshift_cluster_role.name
}

# First node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node1" {
  cluster_identifier = "redshift-cluster-node1"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_type       = "multi-node"
  number_of_nodes    = 2
}

# Second node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node2" {
  cluster_identifier = "redshift-cluster-node2"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_type       = "multi-node"
  number_of_nodes    = 2
}

# Resource policy for the Redshift cluster
resource "aws_redshift_resource_policy" "redshift_cluster_resource_policy" {
  resource_arn = aws_redshift_cluster.redshift_cluster_node1.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:DescribeClusters",
          "redshift:ModifyCluster"
        ]
        Effect   = "Allow"
        Resource = aws_redshift_cluster.redshift_cluster_node1.arn
        Principal = {
          AWS = "*"
        }
      }
    ]
  })
}
```

### Notes
- The IAM role and policy are created to allow the Redshift cluster to access an S3 bucket.
- The Redshift clusters are configured as multi-node clusters with two nodes each.
- The resource policy allows any AWS principal to describe and modify the Redshift cluster. Adjust the policy as needed for your specific security requirements.

