```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_assume_role_policy" {
  name        = "lambda_assume_role_policy"
  description = "Policy for Lambda to assume the execution role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  policy_arn = aws_iam_policy.lambda_assume_role_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "lambda-code-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "lambda_function_code" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "lambda.js"
  source = "lambda.js"
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = "my_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  s3_bucket     = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key        = aws_s3_object.lambda_function_code.key
}
```

