### Description
This Terraform program sets up an AWS Lambda function named `test_lambda` that will be triggered whenever an EC2 image is created. The program includes the necessary IAM roles, policies, and permissions to ensure the Lambda function can execute and be invoked by the EC2 service. It also sets up an S3 bucket to store the Lambda function code and configures a CloudWatch event rule to trigger the Lambda function based on EC2 image creation events.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Function
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda function to access necessary resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach IAM Policy to Lambda Execution Role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# S3 Bucket to store Lambda function code
resource "aws_s3_bucket" "lambda_code_bucket" {
  bucket = "lambda-code-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

# Random string for S3 bucket name uniqueness
resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

# Upload Lambda function code to S3
resource "aws_s3_object" "lambda_code_object" {
  bucket = aws_s3_bucket.lambda_code_bucket.bucket
  key    = "test_lambda.zip"
  source = "./path/to/test_lambda.zip"
}

# Lambda Function
resource "aws_lambda_function" "test_lambda" {
  function_name = "test_lambda"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  s3_bucket     = aws_s3_bucket.lambda_code_bucket.bucket
  s3_key        = aws_s3_object.lambda_code_object.key
}

# Allow EC2 service to invoke the Lambda function
resource "aws_lambda_permission" "allow_ec2_create_trigger" {
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "ec2.amazonaws.com"
}

# CloudWatch Event Rule for EC2 Image Creation
resource "aws_cloudwatch_event_rule" "ec2_image_created_rule" {
  name        = "ec2_image_created_rule"
  description = "Rule to trigger Lambda on EC2 image creation"
  event_pattern = jsonencode({
    "source": ["aws.ec2"],
    "detail-type": ["EC2 Image State Change"],
    "detail": {
      "state": ["available"]
    }
  })
}

# Set the Lambda function as the target for the CloudWatch event rule
resource "aws_cloudwatch_event_target" "trigger_lambda_on_ec2_image_created" {
  rule      = aws_cloudwatch_event_rule.ec2_image_created_rule.name
  target_id = "TriggerLambdaOnEC2ImageCreated"
  arn       = aws_lambda_function.test_lambda.invoke_arn
}
```

This Terraform configuration sets up the necessary AWS resources to trigger a Lambda function whenever an EC2 image is created. The Lambda function code is stored in an S3 bucket, and the IAM roles and policies ensure that the function has the necessary permissions to execute and be invoked by the EC2 service.

