    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id     = aws_vpc.example.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_sagemaker_domain" "example" {
  domain_name = "example"
  auth_mode   = "IAM"
  vpc_id      = aws_vpc.example.id
  subnet_ids  = [aws_subnet.example.id]

  default_user_settings {
    execution_role = aws_iam_role.example.arn
  }
}

resource "aws_iam_role" "example" {
  name               = "example"
  path               = "/"
  assume_role_policy = data.aws_iam_policy_document.example.json
}

data "aws_iam_policy_document" "example" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_sagemaker_user_profile" "example" {
  domain_id         = aws_sagemaker_domain.example.id
  user_profile_name = "example"
}

LLM Output #0:
### Description
This Terraform program creates a SageMaker user profile resource along with the necessary IAM role and policy. The IAM role is attached with a policy that grants the required permissions for SageMaker operations. The SageMaker user profile is then created using this IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_user_profile_role" {
  name = "sagemaker-user-profile-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_user_profile_policy" {
  name        = "sagemaker-user-profile-policy"
  description = "Policy for SageMaker user profile"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:*",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_sagemaker_user_profile_policy_to_role" {
  policy_arn = aws_iam_policy.sagemaker_user_profile_policy.arn
  role       = aws_iam_role.sagemaker_user_profile_role.name
}

resource "aws_sagemaker_user_profile" "sagemaker_user_profile" {
  domain_id         = "example-domain-id"
  user_profile_name = "example-user-profile"

  user_settings {
    execution_role = aws_iam_role.sagemaker_user_profile_role.arn
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `sagemaker-user-profile-role` is created with an assume role policy that allows SageMaker to assume this role.
3. **IAM Policy**: An IAM policy named `sagemaker-user-profile-policy` is created with permissions for SageMaker operations.
4. **IAM Role Policy Attachment**: The policy is attached to the IAM role.
5. **SageMaker User Profile**: A SageMaker user profile is created with the specified domain ID and user profile name, using the IAM role for execution.

