### Description
This Terraform program creates an AWS SageMaker Notebook Instance along with the necessary IAM role and policy. The IAM role is created with a policy that grants the necessary permissions for SageMaker operations. The SageMaker notebook instance is then created using this IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_notebook_role" {
  name = "sagemaker-notebook-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "sagemaker_notebook_policy" {
  name = "sagemaker-notebook-policy"
  role = aws_iam_role.sagemaker_notebook_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:*",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_sagemaker_notebook_instance" "sagemaker_notebook_instance" {
  name         = "sagemaker-notebook-instance"
  instance_type = "ml.t2.medium"
  role_arn     = aws_iam_role.sagemaker_notebook_role.arn

  volume_size = 5
}
```

This Terraform configuration sets up an AWS SageMaker Notebook Instance with the necessary IAM role and policy. The IAM role allows the SageMaker service to assume the role, and the policy grants the role permissions to perform various SageMaker operations. The SageMaker notebook instance is configured with a medium-sized instance type and a 5GB EBS volume.

