### Description
This Terraform program creates a SageMaker Human Task UI resource using an HTML template stored in an S3 bucket. The program includes the creation of an S3 bucket, uploading the HTML template to the bucket, creating an IAM role with necessary permissions, and finally creating the SageMaker Human Task UI.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "sagemaker_human_task_ui_bucket" {
  bucket = "sagemaker-human-task-ui-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_s3_object" "sagemaker_human_task_ui_template" {
  bucket = aws_s3_bucket.sagemaker_human_task_ui_bucket.bucket
  key    = "sagemaker-human-task-ui-template.html"
  content = <<EOF
<h1>
    TEST
</h1>
EOF
}

resource "aws_iam_role" "sagemaker_human_task_ui_role" {
  name = "sagemaker-human-task-ui-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_human_task_ui_policy" {
  name        = "sagemaker-human-task-ui-policy"
  description = "Policy for SageMaker to access S3 bucket for human task UI"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.sagemaker_human_task_ui_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_sagemaker_human_task_ui_policy" {
  policy_arn = aws_iam_policy.sagemaker_human_task_ui_policy.arn
  role       = aws_iam_role.sagemaker_human_task_ui_role.name
}

resource "aws_sagemaker_human_task_ui" "sagemaker_human_task_ui" {
  human_task_ui_name = "sagemaker-human-task-ui"

  ui_template {
    content = aws_s3_object.sagemaker_human_task_ui_template.content
  }
}
```

This Terraform configuration ensures that all dependencies are correctly handled, and the resources are created in the specified order. The S3 bucket is created with a unique name using a random string suffix, and the IAM role and policy are set up to allow SageMaker to access the S3 bucket. Finally, the SageMaker Human Task UI is created using the uploaded HTML template.

