### Description
This Terraform program creates an AWS Lambda function using the Node.js 18 runtime. The function is triggered by an event and uses "lambda.js" as the source code and "index.js" as the handler. The program also sets up an IAM role with the necessary permissions for the Lambda function to execute.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = "my_lambda_function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "nodejs18.x"

  filename         = "lambda.zip"  # Ensure this zip file contains lambda.js and index.js
  source_code_hash = filebase64sha256("lambda.zip")
}
```

### Notes
- Ensure that the `lambda.zip` file contains both `lambda.js` and `index.js`.
- The `source_code_hash` is calculated using the SHA-256 hash of the `lambda.zip` file to ensure Terraform can detect changes to the source code.
- The IAM role and policy attachment ensure that the Lambda function has the necessary permissions to write logs to CloudWatch.

