### Description
This Terraform program creates a VPC with a public and private subnet. It also sets up an EC2 Fleet consisting of 5 On-Demand and 4 Spot instances using AWS Linux 2 as the AMI. The EC2 Fleet uses a launch template that includes an IAM role and instance profile for proper permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2-fleet-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ec2-fleet-instance-profile"
  role = aws_iam_role.ec2_fleet_role.name
}

resource "aws_launch_template" "ec2_fleet_launch_template" {
  name = "ec2-fleet-launch-template"

  image_id      = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  key_name      = "my-key-pair"             # Replace with your key pair name

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  }
}

resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template {
      id      = aws_launch_template.ec2_fleet_launch_template.id
      version = "$Latest"
    }
  }

  target_capacity_specification {
    total_target_capacity     = 9
    default_target_capacity_type = "spot"
    spot_target_capacity      = 4
    on_demand_target_capacity = 5
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  replace_unhealthy_instances = true
}
```

### Notes
- Ensure that the key pair (`my-key-pair`) exists in your AWS account.
- Adjust the AMI ID if necessary to match the latest Amazon Linux 2 AMI in your region.
- The VPC, subnets, and IAM resources are created with basic configurations. You may need to add additional configurations such as route tables and internet gateways for public subnet connectivity.

