### Description
This Terraform program creates an IAM role and policy specifically for authenticating an ElastiCache user. The IAM role is attached with the necessary policy, and an ElastiCache user is created that uses this IAM role for authentication.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasticache_user_auth_role" {
  name = "elasticache-user-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "elasticache_user_auth_policy" {
  name        = "elasticache-user-auth-policy"
  description = "Policy for ElastiCache user authentication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:DescribeUsers",
          "elasticache:ListTagsForResource",
          "elasticache:ModifyUser",
          "elasticache:UpdateUser"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elasticache_policy_to_role" {
  policy_arn = aws_iam_policy.elasticache_user_auth_policy.arn
  role       = aws_iam_role.elasticache_user_auth_role.name
}

resource "aws_elasticache_user" "elasticache_user" {
  user_id     = "elasticache-user"
  user_name   = "elasticache-user"
  access_string = "on ~app::* -@allusers"
  engine      = "redis"

  authentication_mode {
    type = "iam"
  }
}
```

This Terraform configuration sets up the necessary IAM role and policy for authenticating an ElastiCache user. The `aws_iam_role` resource defines the role with an appropriate trust policy for ElastiCache. The `aws_iam_policy` resource defines the policy with permissions required for ElastiCache operations. The `aws_iam_role_policy_attachment` resource attaches the policy to the role. Finally, the `aws_elasticache_user` resource creates an ElastiCache user that uses the IAM role for authentication.

