### Description
This Terraform program creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. The program includes the necessary configuration for the MSK cluster, specifying the required attributes such as the cluster name, Kafka version, and number of broker nodes. Additionally, it sets up the broker node group information, including client subnets, instance type, and security groups. The AWS provider is configured with a default region and credentials.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count             = 3
  vpc_id            = aws_vpc.example.id
  cidr_block        = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  availability_zone = element(data.aws_availability_zones.available.names, count.index)
}

data "aws_availability_zones" "available" {}

resource "aws_security_group" "example" {
  name        = "msk-sg"
  description = "Allow Kafka traffic"
  vpc_id      = aws_vpc.example.id

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = aws_subnet.example[*].id
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.example.id]
  }

  client_authentication {
    unauthenticated {
      enabled = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }

  tags = {
    Name = "My MSK Cluster"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with the region `us-west-2`.
- **VPC and Subnets**: A VPC and three subnets are created to host the MSK cluster.
- **Security Group**: A security group is created to allow inbound traffic on port 9092 and outbound traffic.
- **MSK Cluster**: The MSK cluster is created with the specified name, Kafka version, and number of broker nodes. The broker node group information includes the client subnets, instance type, and security groups. Client authentication is set to unauthenticated, and encryption at rest is enabled using a KMS key ARN. Logging is configured to send broker logs to CloudWatch.

