LLM Output #0:
### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. The program includes the necessary configuration for the MSK cluster, including the broker node group information, security groups, and other required attributes. It also sets up an IAM role for the MSK service to interact with other AWS services.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_security_group" "msk_security_group" {
  name        = "msk-security-group"
  description = "Security group for MSK cluster"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Replace with your CIDR block
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
    instance_type  = "t3.medium"
    security_groups = [aws_security_group.msk_security_group.id]
  }

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }

  tags = {
    Name = "MyMSKCluster"
  }
}
```

### Notes
- Replace `"vpc-12345678"` with your actual VPC ID.
- Replace `["subnet-12345678", "subnet-87654321"]` with your actual subnet IDs.
- Adjust the CIDR block in the security group ingress rule as needed.
- Ensure that the IAM role has the necessary permissions for your use case.

