LLM Output #0:
### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The cluster is configured to log to an S3 bucket. The program also sets up an IAM role and policy to allow the MSK cluster to access the S3 bucket for logging purposes.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  logging {
    target_bucket = aws_s3_bucket.msk_logs_bucket.bucket
    target_prefix = "msk-logs/"
  }

  tags = {
    Name = "MSKLogsBucket"
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "MSKServiceRole"
  }
}

resource "aws_iam_policy" "msk_service_policy" {
  name        = "msk-service-policy"
  description = "Policy for MSK to access S3 for logging"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.msk_logs_bucket.arn}",
          "${aws_s3_bucket.msk_logs_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name = "MSKServicePolicy"
  }
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_service_policy.arn
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
    instance_type  = "t3.medium"
    security_groups = ["sg-0123456789abcdef0"]
  }

  logging_info {
    s3 {
      enabled         = true
      bucket        = aws_s3_bucket.msk_logs_bucket.bucket
      prefix        = "msk-logs/"
    }
  }

  tags = {
    Name = "ManagedMSKCluster"
  }
}
```

### Notes
- The `aws_s3_bucket` resource creates an S3 bucket with logging enabled to itself.
- The `aws_iam_role` and `aws_iam_policy` resources create an IAM role and policy that allow the MSK cluster to access the S3 bucket.
- The `aws_iam_role_policy_attachment` resource attaches the policy to the role.
- The `aws_msk_cluster` resource creates the MSK cluster with logging enabled to the specified S3 bucket.
- Replace the subnet and security group IDs with valid values from your AWS account.

