### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with encryption at rest. It includes the creation of an AWS KMS key for encryption, an IAM role and policy for the MSK service, and attaches the policy to the role. The MSK cluster is then created with the specified encryption key.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "msk_encryption_key" {
  description             = "KMS key for MSK encryption at rest"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_service_policy" {
  name        = "msk-service-policy"
  description = "Policy for MSK service role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.msk_encryption_key.arn
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_service_policy.arn
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "t3.medium"
    security_groups = ["sg-12345678"]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_encryption_key.arn
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **KMS Key**: An AWS KMS key is created for encrypting the MSK cluster data at rest.
3. **IAM Role**: An IAM role is created for the MSK service with a trust policy allowing EC2 to assume the role.
4. **IAM Policy**: An IAM policy is created granting the necessary permissions for the MSK service to use the KMS key and write logs to CloudWatch.
5. **IAM Role Policy Attachment**: The IAM policy is attached to the IAM role.
6. **MSK Cluster**: A managed MSK cluster is created with the specified KMS key for encryption at rest. The cluster is configured with three broker nodes, using the `t3.medium` instance type, and specified subnets and security groups.

