Below is a complete Terraform HCL program that creates a managed MSK cluster with JMX Exporter and Node Exporter both enabled. The program includes the necessary IAM roles, policies, S3 buckets, and MSK configurations.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_policy" {
  name        = "msk-cluster-policy"
  description = "Policy for MSK cluster operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.jmx_exporter_logs_bucket.arn}/*",
          "${aws_s3_bucket.node_exporter_logs_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
  role       = aws_iam_role.msk_cluster_role.name
}

resource "aws_s3_bucket" "jmx_exporter_logs_bucket" {
  bucket = "jmx-exporter-logs-bucket-${random_string.suffix.result}"
}

resource "aws_s3_bucket" "node_exporter_logs_bucket" {
  bucket = "node-exporter-logs-bucket-${random_string.suffix.result}"
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_msk_configuration" "jmx_exporter_config" {
  name               = "jmx-exporter-config"
  server_properties = file("${path.module}/jmx_exporter.properties")
}

resource "aws_msk_configuration" "node_exporter_config" {
  name               = "node-exporter-config"
  server_properties = file("${path.module}/node_exporter.properties")
}

resource "aws_msk_configuration" "combined_config" {
  name               = "combined-config"
  server_properties = file("${path.module}/combined.properties")
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "t3.medium"
    security_groups = ["sg-12345678"]
  }

  configuration_info {
    arn      = aws_msk_configuration.combined_config.arn
    revision = aws_msk_configuration.combined_config.latest_revision
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role and Policy**: An IAM role (`msk-cluster-role`) is created with an assume role policy that allows EC2 to assume the role. An IAM policy (`msk-cluster-policy`) is created with permissions for logging and S3 access. The policy is attached to the role.
3. **S3 Buckets**: Two S3 buckets (`jmx-exporter-logs-bucket` and `node-exporter-logs-bucket`) are created to store logs for JMX and Node Exporters.
4. **MSK Configurations**: Three MSK configurations are created:
   - `jmx-exporter-config` for JMX Exporter settings.
   - `node-exporter-config` for Node Exporter settings.
   - `combined-config` that combines both JMX and Node Exporter settings.
5. **MSK Cluster**: A managed MSK cluster (`managed-msk-cluster`) is created with three broker nodes. The combined configuration is applied to the cluster, and Open Monitoring is enabled with both JMX and Node Exporters.

Make sure to replace the placeholder values (e.g., subnet IDs, security group IDs) with actual values from your AWS account. Additionally, ensure that the `jmx_exporter.properties`, `node_exporter.properties`, and `combined.properties` files exist in the same directory as your Terraform configuration.

