### Description
This Terraform program creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. It also sets up an IAM role and attaches the necessary policy for the MSK service to operate correctly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type  = "t3.medium"
    security_groups = ["sg-0123456789abcdef0"]
  }

  client_authentication {
    unauthenticated {
      enabled = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }

  tags = {
    Name = "MyMSKCluster"
  }
}
```

### Notes
- The `client_subnets` and `security_groups` should be replaced with actual subnet IDs and security group IDs from your VPC.
- The `encryption_at_rest_kms_key_arn` should be replaced with a valid KMS key ARN.
- Ensure that the IAM role and policy attachment are correctly configured to meet your security requirements.

