### Description
This Terraform program creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-2` region. It includes the necessary IAM role and policy attachments required for the MSK cluster to operate. The program defines the following resources:

1. **AWS Provider Configuration**: Configures the AWS provider to use the `us-east-2` region.
2. **IAM Role for MSK**: Creates an IAM role named `msk-service-role` with an assume role policy that allows the MSK service to assume the role.
3. **IAM Policy for MSK**: Defines an IAM policy named `msk-service-policy` with permissions required by the MSK cluster.
4. **IAM Role Policy Attachment**: Attaches the `msk-service-policy` to the `msk-service-role`.
5. **MSK Cluster**: Creates a serverless MSK cluster named `my-msk-cluster` with specified configurations such as Kafka version, number of broker nodes, and broker node group information.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_service_policy" {
  name        = "msk-service-policy"
  description = "Policy for MSK service"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:*",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  policy_arn = aws_iam_policy.msk_service_policy.arn
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
    instance_type  = "t3.medium"
    security_groups = ["sg-0123456789abcdef0"]
  }

  client_authentication {
    unauthenticated {
      enabled = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }

  tags = {
    Name = "MyMSKCluster"
  }
}
```

### Notes
- **Subnet IDs and Security Group IDs**: Replace `"subnet-0123456789abcdef0"` and `"sg-0123456789abcdef0"` with actual subnet and security group IDs from your VPC.
- **KMS Key ARN**: Replace `"arn:aws:kms:us-east-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"` with a valid KMS key ARN for encryption at rest.
- **CloudWatch Log Group**: Ensure the CloudWatch log group `/aws/msk/my-msk-cluster` exists or adjust the log group name as needed.

Rego intent:
package main

import future.keywords.in

default allow = false

# Check for MSK Cluster creation
msk_cluster_created(resources) {
some resource in resources
resource.type == "aws_msk_cluster"
resource.change.actions[_] == "create"
}

# Check if the MSK cluster is in us-east-1 (as defined in Terraform)
msk_cluster_region_valid(resource) {
resource.type == "aws_msk_cluster"
input.configuration.provider_config.aws.expressions.region.constant_value == "us-east-1"
}

# Check if the MSK cluster has 3 broker nodes (as defined in Terraform)
broker_node_count_valid(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.number_of_broker_nodes == 3
}

# Check if CloudWatch logging is enabled for broker logs
cloudwatch_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].cloudwatch_logs[_].enabled == true
}

# Check if S3 logging is enabled for broker logs
s3_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].s3[_].enabled == true
}

# Check if Kinesis Firehose logging is enabled for broker logs
firehose_logging_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.logging_info[_].broker_logs[_].firehose[_].enabled == true
}

# Check if encryption at rest is enabled
encryption_at_rest_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after_unknown.encryption_info[_].encryption_at_rest_kms_key_arn
}

# Check if both jmx_exporter and node_exporter are enabled
prometheus_exporters_enabled(resource) {
resource.type == "aws_msk_cluster"
resource.change.after.open_monitoring[_].prometheus[_].jmx_exporter[_].enabled_in_broker == true
resource.change.after.open_monitoring[_].prometheus[_].node_exporter[_].enabled_in_broker == true
}

# Aggregate all checks
allow {
msk_cluster_created(input.resource_changes)
some resource in input.resource_changes
msk_cluster_region_valid(resource)
broker_node_count_valid(resource)
cloudwatch_logging_enabled(resource)
s3_logging_enabled(resource)
firehose_logging_enabled(resource)
encryption_at_rest_enabled(resource)
prometheus_exporters_enabled(resource)
}

