Below is a complete Terraform HCL program that creates an MSK cluster with 3 broker nodes, outputs to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. The MSK cluster is configured with encryption at rest and open monitoring.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "msk_kinesis_firehose_role" {
  name = "msk-kinesis-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_kinesis_firehose_policy" {
  name        = "msk-kinesis-firehose-policy"
  description = "Policy for MSK to deliver logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.msk_logs_bucket.arn,
          "${aws_s3_bucket.msk_logs_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_kinesis_firehose_policy" {
  policy_arn = aws_iam_policy.msk_kinesis_firehose_policy.arn
  role       = aws_iam_role.msk_kinesis_firehose_role.name
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
}

resource "aws_cloudwatch_log_group" "msk_log_group" {
  name = "/aws/msk/cluster"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name = "msk-firehose-delivery-stream"

  extended_s3_configuration {
    role_arn           = aws_iam_role.msk_kinesis_firehose_role.arn
    bucket_arn         = aws_s3_bucket.msk_logs_bucket.arn
    buffering_interval = 60
    buffering_size     = 5
  }
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]
    instance_type  = "t3.medium"
    security_groups = ["sg-12345678"]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.name
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration sets up the required resources and dependencies as described in the prompt. It includes an IAM role and policy for MSK to deliver logs to Kinesis Firehose, an S3 bucket for storing logs, a CloudWatch log group, a Kinesis Firehose delivery stream, and an MSK cluster with logging and encryption configurations.

