Below is a complete Terraform HCL program that creates a managed MSK cluster with 3 broker nodes, an MSK Connect custom plugin using a "debezium.zip" file, and an MSK Connect connector that uses the custom plugin and connects to the MSK cluster.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-13579246"]
    instance_type  = "m5.large"
    security_groups = ["sg-12345678"]
  }

  client_authentication {
    unauthenticated {}
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/my-msk-cluster"
      }
    }
  }
}

resource "aws_iam_role" "msk_connect_plugin_role" {
  name = "msk-connect-plugin-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafkaconnect.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_connect_plugin_policy" {
  name        = "msk-connect-plugin-policy"
  description = "Policy for MSK Connect custom plugin"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::my-bucket",
          "arn:aws:s3:::my-bucket/debezium.zip"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_connect_plugin_policy" {
  policy_arn = aws_iam_policy.msk_connect_plugin_policy.arn
  role       = aws_iam_role.msk_connect_plugin_role.name
}

resource "aws_mskconnect_custom_plugin" "msk_connect_custom_plugin" {
  name         = "debezium-custom-plugin"
  content_type = "ZIP"

  location {
    s3_location {
      bucket_arn = "arn:aws:s3:::my-bucket"
      file_key   = "debezium.zip"
    }
  }
}

resource "aws_iam_role" "msk_connect_connector_role" {
  name = "msk-connect-connector-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafkaconnect.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_connect_connector_policy" {
  name        = "msk-connect-connector-policy"
  description = "Policy for MSK Connect connector"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "msk:DescribeCluster",
          "msk:GetBootstrapBrokers"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_connect_connector_policy" {
  policy_arn = aws_iam_policy.msk_connect_connector_policy.arn
  role       = aws_iam_role.msk_connect_connector_role.name
}

resource "aws_mskconnect_connector" "msk_connect_connector" {
  name                  = "my-msk-connector"
  kafkaconnect_version  = "2.8.1"
  service_execution_role_arn = aws_iam_role.msk_connect_connector_role.arn

  connector_configuration = {
    "connector.class" = "io.debezium.connector.kafka.KafkaConnector"
    "tasks.max"       = "1"
    "topics"          = "my-topic"
    "kafka.bootstrap.servers" = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
  }

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
      vpc {
        security_groups = ["sg-12345678"]
        subnets         = ["subnet-12345678", "subnet-87654321", "subnet-13579246"]
      }
    }
  }

  plugin {
    custom_plugin {
      arn     = aws_mskconnect_custom_plugin.msk_connect_custom_plugin.arn
      revision = aws_mskconnect_custom_plugin.msk_connect_custom_plugin.latest_revision
    }
  }
}
```

This Terraform configuration sets up the necessary resources to create an MSK cluster, an MSK Connect custom plugin, and an MSK Connect connector. Ensure that the S3 bucket and the "debezium.zip" file are properly configured and accessible. Adjust the subnet IDs, security group IDs, and KMS key ARN as needed for your environment.

