### Description
This Terraform program creates a DynamoDB table in the `us-east-1` region and sets up a global table to replicate the DynamoDB table across the `us-east-2` and `us-west-2` regions. The program includes the necessary AWS provider configuration and IAM roles for managing the DynamoDB resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "dynamodb_role" {
  name = "dynamodb-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "dynamodb_policy" {
  name = "dynamodb-replication-policy"
  role = aws_iam_role.dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = "my-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"
  read_capacity  = 1
  write_capacity = 1

  attribute {
    name = "id"
    type = "S"
  }

  replica {
    region_name = "us-east-2"
  }

  replica {
    region_name = "us-west-2"
  }

  timeouts {
    create = "10m"
    update = "10m"
    delete = "10m"
  }
}

resource "aws_dynamodb_global_table" "global_dynamodb_table" {
  name = "my-global-dynamodb-table"

  replica {
    region_name = "us-east-1"
  }

  replica {
    region_name = "us-east-2"
  }

  replica {
    region_name = "us-west-2"
  }

  timeouts {
    create = "10m"
    update = "10m"
    delete = "10m"
  }
}
```

This Terraform configuration sets up a DynamoDB table with replicas in `us-east-2` and `us-west-2`. It also includes an IAM role and policy necessary for managing the replication process. The `aws_dynamodb_global_table` resource ensures that the table is replicated across the specified regions.

