This Terraform program creates an AWS Virtual Private Cloud (VPC) with one public subnet and one private subnet. The VPC is configured with a CIDR block of `10.0.0.0/16`. The public subnet is assigned a CIDR block of `10.0.1.0/24` and is mapped to a public IP on launch. The private subnet is assigned a CIDR block of `10.0.2.0/24` and is not mapped to a public IP on launch.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
