```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_chime_voice_connector" "voice_connector" {
  name              = "MyChimeVoiceConnector"
  require_encryption = true
}

resource "aws_kms_key" "encryption_kms_key" {
  description             = "KMS key for Chime Voice Connector encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_chime_voice_connector_origination" "voice_connector_origination" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
