### Description
This Terraform program sets up an AWS Chime Voice Connector and configures it to stream media to an Amazon Kinesis stream. It includes the necessary IAM role and policy to allow the Chime Voice Connector to access the Kinesis stream. The program also sets up termination and origination configurations for the voice connector.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_chime_voice_connector" "voice_connector" {
  name              = "MyChimeVoiceConnector"
  require_encryption = true
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name             = "MyChimeKinesisStream"
  shard_count      = 1
  retention_period = 24
}

resource "aws_iam_role" "chime_kinesis_role" {
  name = "ChimeKinesisRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "chime.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "chime_kinesis_policy" {
  name        = "ChimeKinesisPolicy"
  description = "Allows Chime to put records into Kinesis"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_stream.kinesis_stream.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_chime_kinesis_policy" {
  policy_arn = aws_iam_policy.chime_kinesis_policy.arn
  role       = aws_iam_role.chime_kinesis_role.name
}

resource "aws_chime_voice_connector_termination" "voice_connector_termination" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
  calling_regions    = ["US"]
  cidr_allow_list    = ["0.0.0.0/0"]
}

resource "aws_chime_voice_connector_origination" "voice_connector_origination" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id

  route {
    host     = "example.com"
    priority = 1
    protocol = "TCP"
    weight   = 1
  }
}
```

This Terraform configuration creates the necessary AWS resources to set up a Chime Voice Connector and stream media to a Kinesis stream. It includes IAM roles and policies to ensure proper permissions. The termination and origination configurations are set up with basic settings, which can be adjusted based on specific requirements.

