### Description
This Terraform program creates an AWS Redshift cluster with endpoint access from two subnets. It includes the necessary resources such as a VPC, two subnets, a security group, and the Redshift cluster itself. The security group is configured to allow necessary inbound and outbound traffic for Redshift.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "redshift_sg" {
  vpc_id = aws_vpc.redshift_vpc.id
  name   = "redshift-sg"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  cluster_subnet_group_name = aws_redshift_subnet_group.redshift_subnet_group.name
  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "my-redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnets**: Two subnets are created within the VPC, each in different availability zones (`us-west-2a` and `us-west-2b`).
- **Security Group**: A security group is created to allow inbound traffic on port 5439 (default Redshift port) from any IP address. Outbound traffic is allowed to any IP address.
- **Redshift Cluster**: A Redshift cluster is created with the specified node type, username, and password. It uses the subnet group and security group created earlier.
- **Redshift Subnet Group**: A subnet group is created to associate the two subnets with the Redshift cluster.

