### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kms_key" "s3_bucket_encryption_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "s3.amazonaws.com"
        },
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "my_s3_bucket" {
  bucket = "my-unique-s3-bucket-name"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "aws:kms"
        kms_master_key_id = aws_kms_key.s3_bucket_encryption_key.arn
      }
    }
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **KMS Key Creation**: An AWS KMS key is created with a description, a deletion window of 10 days, and key rotation enabled. The policy allows the S3 service to use the key for encryption.
3. **S3 Bucket Creation**: An S3 bucket is created with a unique name. The server-side encryption configuration is set to use the KMS key created earlier for encrypting the objects stored in the bucket.

