This Terraform program creates an S3 bucket named `example-payment-bucket` to store payment-related data. It also defines an S3 bucket policy to control access to the payment configuration. The bucket is configured with basic settings, and the policy allows read and write access from a specific IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "example_payment_bucket" {
  bucket = "example-payment-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_iam_role" "payment_access_role" {
  name = "payment-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "payment_access_policy" {
  name        = "payment-access-policy"
  description = "Policy to allow access to the payment S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::example-payment-bucket/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_payment_policy" {
  role       = aws_iam_role.payment_access_role.name
  policy_arn = aws_iam_policy.payment_access_policy.arn
}

resource "aws_s3_bucket_policy" "example_payment_bucket_policy" {
  bucket = aws_s3_bucket.example_payment_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::example-payment-bucket/*"
        Principal = {
          AWS = aws_iam_role.payment_access_role.arn
        }
      }
    ]
  })
}
```

This Terraform configuration sets up an S3 bucket for storing payment-related data, creates an IAM role with permissions to access the bucket, and attaches a policy to the role. The bucket policy ensures that only the specified IAM role can read from and write to the bucket.

