  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "s3:GetBucketAcl"
        Resource  = "${aws_s3_bucket.logging_bucket.arn}"
      },
      {
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.logging_bucket.arn}/log/*"
        Condition = {
