### Description
This Terraform program sets up an AWS CodeBuild project for an autograder that runs students' code stored on GitHub and stores the results. It includes the necessary IAM roles and policies to allow CodeBuild to access GitHub and store results in AWS S3.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_autograder_policy" {
  name        = "codebuild-autograder-policy"
  description = "Policy for CodeBuild to access GitHub and store results"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::autograder-results/*"
      },
      {
        Action = [
          "github:ListRepos",
          "github:GetRepo",
          "github:GetContents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  policy_arn = aws_iam_policy.codebuild_autograder_policy.arn
  role       = aws_iam_role.codebuild_autograder_role.name
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder-project"
  service_role = aws_iam_role.codebuild_autograder_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    report_build_status = true
  }

  artifacts {
    type = "S3"
    location = "autograder-results"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `codebuild-autograder-role` is created with a trust policy allowing CodeBuild to assume the role.
3. **IAM Policy**: An IAM policy named `codebuild-autograder-policy` is created with permissions to log to CloudWatch, access S3 for storing results, and access GitHub for fetching student code.
4. **IAM Role Policy Attachment**: The policy is attached to the IAM role.
5. **CodeBuild Project**: A CodeBuild project named `autograder-project` is created with the specified IAM role, GitHub source, S3 artifacts, and a Linux container environment.

