### Description
This Terraform program sets up the infrastructure for an autograder that runs students' code stored on GitHub and stores the results in an AWS S3 bucket. The program includes the following resources:

1. **AWS S3 Bucket**: A bucket to store the results of the autograder.
2. **AWS IAM Role**: An IAM role for AWS CodeBuild to access necessary resources.
3. **AWS IAM Policy**: A policy to allow AWS CodeBuild to access the S3 bucket.
4. **AWS IAM Role Policy Attachment**: Attaches the S3 access policy to the CodeBuild IAM role.
5. **AWS CodeBuild Project**: A CodeBuild project to run students' code.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "autograder_results_bucket" {
  bucket = "autograder-results-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "AutograderResultsBucket"
    Environment = "production"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CodeBuildAutograderRole"
    Environment = "production"
  }
}

resource "aws_iam_policy" "codebuild_s3_access_policy" {
  name        = "codebuild-s3-access-policy"
  description = "Policy to allow AWS CodeBuild to access the S3 bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.autograder_results_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_s3_policy" {
  policy_arn = aws_iam_policy.codebuild_s3_access_policy.arn
  role       = aws_iam_role.codebuild_autograder_role.name
}

resource "aws_codebuild_project" "autograder_codebuild_project" {
  name         = "autograder-codebuild-project"
  service_role = aws_iam_role.codebuild_autograder_role.arn

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    buildspec       = "buildspec.yml"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:us-west-2:123456789012:project/autograder-codebuild-project"
    }
  }

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  tags = {
    Name        = "AutograderCodeBuildProject"
    Environment = "production"
  }
}
```

This Terraform configuration sets up the necessary AWS resources to run an autograder using AWS CodeBuild and store the results in an S3 bucket. The IAM role and policy ensure that CodeBuild has the necessary permissions to access the S3 bucket.

