### Description
This Terraform program sets up an isolated environment for an autograder using AWS CodeBuild and AWS VPC. The environment is designed to prevent students' code from reaching the internet by isolating it within a VPC with a private subnet. The program includes the creation of a VPC, subnet, internet gateway, route table, security group, and a CodeBuild project. The security group is configured to restrict outbound traffic to prevent the students' code from accessing the internet.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "AutograderVPC"
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "AutograderSubnet"
  }
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "AutograderIGW"
  }
}

resource "aws_route_table" "autograder_public_rt" {
  vpc_id = aws_vpc.autograder_vpc.id
  tags = {
    Name = "AutograderPublicRT"
  }
}

resource "aws_route" "autograder_internet_route" {
  route_table_id         = aws_route_table.autograder_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

resource "aws_route_table_association" "autograder_subnet_assoc" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_public_rt.id
}

resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "AutograderSG"

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AutograderSG"
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "AutograderProject"
  service_role = "arn:aws:iam::aws:policy/service-role/AWSCodeBuildServiceRole"

  source {
    type            = "GITHUB"
    location          = "https://github.com/example/repo.git"
    buildspec         = "buildspec.yml"
    auth {
      type     = "OAUTH"
      resource = "arn:aws:codebuild:us-west-2:123456789012:project/AutograderProject"
    }
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "AutograderProject"
  }
}
```

This Terraform configuration sets up a VPC with a private subnet, an internet gateway, and a route table to allow outbound traffic. The security group is configured to allow SSH access from anywhere and restricts all other outbound traffic. The CodeBuild project is set up to pull code from a GitHub repository and run it within the isolated VPC environment.

