### Description
This Terraform program sets up an AWS environment for storing code build outputs using an S3 bucket, and configures a CodeBuild project within a VPC with restricted internet access. The resources created include:

1. **AWS S3 Bucket**: To store the output of the CodeBuild project.
2. **AWS VPC**: A virtual private cloud with a specified CIDR block.
3. **AWS Subnet**: A subnet within the VPC.
4. **AWS Security Group**: A security group linked to the VPC with no ingress or egress rules to block internet access.
5. **AWS CodeBuild Project**: A CodeBuild project configured to use the S3 bucket for artifacts, with a specified environment and source.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "code_build_output_bucket" {
  bucket = "code-build-output-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "CodeBuildOutputBucket"
    Environment = "production"
  }
}

resource "random_string" "suffix" {
  length  = 8
  special = false
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "MainVPC"
    Environment = "production"
  }
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name        = "MainSubnet"
    Environment = "production"
  }
}

resource "aws_security_group" "main_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "main-security-group"

  # No ingress or egress rules to block internet access
  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    self        = true
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
    self        = true
  }

  tags = {
    Name        = "MainSecurityGroup"
    Environment = "production"
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CodeBuildServiceRole"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSCodeBuildDeveloperAccess"
}

resource "aws_codebuild_project" "students_codebuild_project" {
  name         = "students-codebuild-project"
  service_role = aws_iam_role.codebuild_service_role.arn

  artifacts {
    type = "S3"
    location = "${aws_s3_bucket.code_build_output_bucket.bucket}/artifacts"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "alpine"
    type         = "LINUX_CONTAINER"
  }

  source {
    type         = "GITHUB"
    location     = "github.com/source-location"
    git_clone_depth = 1
  }

  vpc_config {
    vpc_id             = aws_vpc.main_vpc.id
    subnets            = [aws_subnet.main_subnet.id]
    security_group_ids = [aws_security_group.main_security_group.id]
  }

  tags = {
    Name        = "StudentsCodeBuildProject"
    Environment = "production"
  }
}
```

