### Description
This Terraform program provisions an AWS EC2 instance and sets up a daily backup using AWS Backup. The program includes the creation of an EC2 key pair, an EC2 instance, an AWS Backup vault, a backup plan, and a backup selection. The backup plan is configured to run daily at midnight.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_key_pair" "ec2_key_pair" {
  key_name   = "my-ec2-key-pair"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t3.micro"
  key_name      = aws_key_pair.ec2_key_pair.key_name

  tags = {
    Name = "MyEC2Instance"
  }
}

resource "aws_backup_vault" "backup_vault" {
  name        = "my-backup-vault"
  kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"  # Replace with your KMS key ARN
}

resource "aws_backup_plan" "backup_plan" {
  name = "my-backup-plan"

  rule {
    rule_name         = "DailyBackup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = "arn:aws:iam::123456789012:role/service-role/AWSBackupDefaultServiceRole"  # Replace with your IAM role ARN
  plan_id      = aws_backup_plan.backup_plan.id
  name         = "my-backup-selection"

  resources = [
    aws_instance.ec2_instance.arn
  ]
}
```

### Notes
- Ensure the AWS Backup service is enabled in your AWS account.
- Replace the `kms_key_arn` and `iam_role_arn` with valid values from your AWS account.
- The EC2 instance uses an example AMI ID for Amazon Linux 2. You may need to replace it with an appropriate AMI ID for your region.
- The backup plan is configured to run daily at midnight using a cron expression.

