  runtime       = "python3.12"
  role          = aws_iam_role.lambda_execution_role.arn
}

resource "aws_lambda_permission" "cron_lambda_permission" {
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron_lambda_function.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_eventbridge_rule.cron_event_rule.arn
}

resource "aws_eventbridge_rule" "cron_event_rule" {
  name                = "cron"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_eventbridge_target" "cron_event_target" {
  rule      = aws_eventbridge_rule.cron_event_rule.name
  target_id = "cron-lambda-target"

  arn = aws_lambda_function.cron_lambda_function.invoke_arn
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **IAM Role**: An IAM role named `lambda-execution-role` is created with a trust policy allowing Lambda to assume the role.
3. **IAM Role Policy Attachment**: The `AWSLambdaBasicExecutionRole` policy is attached to the IAM role to allow basic logging to CloudWatch.
4. **Lambda Function**: A Lambda function named `cron-lambda-function` is created with the specified code, handler, and runtime. It uses the IAM role created earlier.
5. **Lambda Permission**: A permission is granted to the EventBridge service to invoke the Lambda function.
6. **EventBridge Rule**: An EventBridge rule named `cron` is created with a cron expression to trigger the event every day at 7 UTC.
7. **EventBridge Target**: The EventBridge rule is linked to the Lambda function as a target, specifying the Lambda function's invoke ARN.

