### Description
This Terraform program sets up the infrastructure for a video streaming site using AWS CloudFront and AWS S3. The program creates an S3 bucket to store video content, an IAM role and policy to allow CloudFront to access the S3 bucket, an origin access identity for CloudFront, a bucket policy to grant CloudFront access to the S3 bucket, and a CloudFront distribution to serve the video content globally.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "unique-video-content-bucket-name"
  acl    = "private"
}

resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "cloudfront-origin-access-identity-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_read_policy" {
  name        = "s3-read-policy"
  description = "Policy allowing read access to S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_read_policy_to_role" {
  policy_arn = aws_iam_policy.s3_read_policy.arn
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
}

resource "aws_cloudfront_origin_access_identity" "video_content_origin_access_identity" {
  comment = "Origin access identity for CloudFront to access S3 bucket"
}

resource "aws_s3_bucket_policy" "bucket_policy_for_cloudfront" {
  bucket = aws_s3_bucket.video_content_bucket.bucket

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.iam_arn
        }
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_content_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled = true

  origin {
    domain_name = "${aws_s3_bucket.video_content_bucket.bucket}.s3.amazonaws.com"
    origin_id   = "S3-${aws_s3_bucket.video_content_bucket.bucket}"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    allowed_methods   = ["GET", "HEAD"]
    cached_methods    = ["GET", "HEAD"]
    target_origin_id  = "S3-${aws_s3_bucket.video_content_bucket.bucket}"
    viewer_protocol_policy = "redirect-to-https"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}
```

This Terraform configuration sets up the necessary AWS resources to distribute video content globally using CloudFront and S3. The S3 bucket stores the video content, and CloudFront serves it to users worldwide. The IAM role and policy ensure that CloudFront has the necessary permissions to access the S3 bucket.

