This Terraform program sets up a Virtual Private Cloud (VPC) with a public subnet and a security group specifically for database access. It then creates a MySQL database instance within the VPC, secured by the designated security group. The MySQL instance uses version 8.4.3 and has a storage capacity of 5GB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet1"
  }
}

resource "aws_security_group" "database_access_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "DatabaseAccessSG"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to restrict access as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseAccessSG"
  }
}

resource "aws_db_instance" "mysql_database" {
  engine               = "mysql"
  engine_version       = "8.4.3"
  instance_class       = "db.t3.micro"
  allocated_storage    = 5
  username             = "admin"
  password             = "securepassword"
  db_name              = "mydatabase"
  parameter_group_name = "default.mysql8.0"
  vpc_security_group_ids = [aws_security_group.database_access_sg.id]
  db_subnet_group_name = "default"  # Using the default subnet group for simplicity

  tags = {
    Name = "MySQLDatabase"
  }
}
```

### Notes
- **CIDR Blocks**: The VPC and subnet CIDR blocks are set to `10.0.0.0/16` and `10.0.1.0/24`, respectively. These can be adjusted based on your network requirements.
- **Security Group Rules**: The security group allows inbound traffic on port 3306 (MySQL) from any IP address (`0.0.0.0/0`). This should be restricted to specific IP addresses or ranges for security purposes.
- **Database Credentials**: The `username` and `password` for the MySQL database are hardcoded. In a production environment, these should be managed securely, possibly using Terraform's `random_password` resource or AWS Secrets Manager.
- **Instance Class and Storage**: The instance class is set to `db.t3.micro` and the storage to 5GB. These can be adjusted based on performance and cost considerations.

