Below is a complete Terraform HCL program that provisions a secure PostgreSQL database instance within a specified AWS VPC, leveraging AWS services like RDS, subnets, and KMS for encryption. It sets up a custom parameter group for PostgreSQL settings, and a security group to manage access. The database instance is configured with specifications like storage size, engine version, multi-AZ deployment for high availability, and encryption using a KMS key. The database instance is configured with "pgsnapshot" as the final snapshot identifier.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "database_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "DatabaseVPC"
  }
}

resource "aws_subnet" "database_subnet_1" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
  tags = {
    Name = "DatabaseSubnet1"
  }
}

resource "aws_subnet" "database_subnet_2" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "DatabaseSubnet2"
  }
}

resource "aws_security_group" "database_sg" {
  vpc_id = aws_vpc.database_vpc.id
  name   = "DatabaseSecurityGroup"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseSecurityGroup"
  }
}

resource "aws_db_parameter_group" "database_param_group" {
  name   = "PostgreSQLParameterGroup"
  family = "postgres13"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name  = "shared_buffers"
    value = "256MB"
  }

  tags = {
    Name = "PostgreSQLParameterGroup"
  }
}

resource "aws_kms_key" "database_kms_key" {
  description             = "KMS Key for Database Encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = {
    Name = "DatabaseKMSKey"
  }
}

resource "aws_db_instance" "database_instance" {
  identifier              = "secure-postgres-db"
  instance_class          = "db.t3.medium"
  engine                  = "postgres"
  engine_version          = "13.7"
  allocated_storage       = 20
  storage_encrypted       = true
  kms_key_id              = aws_kms_key.database_kms_key.arn
  db_subnet_group_name    = aws_db_subnet_group.database_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.database_sg.id]
  parameter_group_name    = aws_db_parameter_group.database_param_group.name
  multi_az                = true
  final_snapshot_identifier = "pgsnapshot"
  skip_final_snapshot     = false

  tags = {
    Name = "SecurePostgresDB"
  }
}

resource "aws_db_subnet_group" "database_subnet_group" {
  name       = "DatabaseSubnetGroup"
  subnet_ids = [aws_subnet.database_subnet_1.id, aws_subnet.database_subnet_2.id]

  tags = {
    Name = "DatabaseSubnetGroup"
  }
}
```

