}

resource "aws_db_instance" "airbyte_postgresql" {
  identifier              = "airbyte-postgresql"
  instance_class          = "db.t3.micro"
  engine                  = "postgres"
  engine_version          = "15"
  allocated_storage       = 20
  username                = "airbyte"
  password                = "securepassword"
  db_subnet_group_name    = aws_db_subnet_group.airbyte_db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.default.id]
  skip_final_snapshot     = true
  apply_immediately       = true
  iam_database_authentication_enabled = true
}

resource "aws_security_group" "default" {
  name        = "airbyte-postgresql-sg"
  description = "Security group for Airbyte PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
