### Description
This Terraform program sets up an AWS environment with a main VPC, two public subnets across different availability zones, and a security group to allow database access. It also configures a MySQL RDS instance with public accessibility, linked to the defined subnets and security group, and outputs the database endpoint for connectivity.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_public_a" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_public_b" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "db-security-group"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_instance" "mysql_rds_instance" {
  instance_class = "db.t3.micro"
  engine         = "mysql"
  engine_version = "8.0"
  username       = "admin"
  password       = "password"
  db_name        = "mydatabase"
  publicly_accessible = true
  skip_final_snapshot = true

  vpc_security_group_ids = [aws_security_group.db_security_group.id]
  db_subnet_group_name   = aws_db_subnet_group.rds_subnet_group.name
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = [aws_subnet.subnet_public_a.id, aws_subnet.subnet_public_b.id]
}

output "database_endpoint" {
  value = aws_db_instance.mysql_rds_instance.endpoint
}
```

