### Description
This Terraform program sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. It includes the necessary networking resources such as a VPC, subnet, and security group. The PostgreSQL database instance is configured with specific details like engine version, instance size, and storage.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "custom_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "CustomVPC"
  }
}

resource "aws_subnet" "custom_subnet" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "CustomSubnet"
  }
}

resource "aws_security_group" "postgres_sg" {
  vpc_id = aws_vpc.custom_vpc.id
  name   = "PostgreSQLSecurityGroup"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this for security best practices
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "PostgreSQLSecurityGroup"
  }
}

resource "aws_db_instance" "postgres_db" {
  instance_class      = "db.t3.micro"
  engine              = "postgres"
  engine_version      = "13.7"
  allocated_storage   = 20
  username            = "admin"
  password            = "securepassword"
  db_name             = "mydatabase"
  skip_final_snapshot = true
  vpc_security_group_ids = [aws_security_group.postgres_sg.id]
  db_subnet_group_name = aws_db_subnet_group.default.name
  tags = {
    Name = "PostgreSQLDBInstance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default"
  subnet_ids = [aws_subnet.custom_subnet.id]

  tags = {
    Name = "DefaultDBSubnetGroup"
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A custom VPC is created with a CIDR block of `10.0.0.0/16`.
- **Subnet**: A subnet is created within the VPC with a CIDR block of `10.0.1.0/24` and mapped to the `us-west-2a` availability zone.
- **Security Group**: A security group is created to allow inbound traffic on port 5432 (PostgreSQL) from any IP address (`0.0.0.0/0`). Outbound traffic is allowed to any destination.
- **Database Instance**: A PostgreSQL database instance is created with the following specifications:
  - Instance class: `db.t3.micro`
  - Engine version: `13.7`
  - Allocated storage: `20` GB
  - Username: `admin`
  - Password: `securepassword`
  - Database name: `mydatabase`
- **DB Subnet Group**: A default DB subnet group is created to associate the database instance with the custom subnet.

