### Description
This Terraform program sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. The database instance is configured to allow major version upgrades, automatically perform minor version upgrades, and is not publicly accessible. The necessary networking resources, including a VPC, subnet, and security group, are also created.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "custom_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "CustomVPC"
  }
}

resource "aws_subnet" "custom_subnet" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "CustomSubnet"
  }
}

resource "aws_security_group" "db_security_group" {
  vpc_id = aws_vpc.custom_vpc.id
  name   = "PostgreSQLSecurityGroup"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "PostgreSQLSecurityGroup"
  }
}

resource "aws_db_instance" "postgres_db" {
  instance_class          = "db.t3.micro"
  engine                  = "postgres"
  engine_version          = "13.7"
  allocated_storage       = 20
  username                = "admin"
  password                = "securepassword"
  db_name                 = "mydatabase"
  skip_final_snapshot     = true
  vpc_security_group_ids  = [aws_security_group.db_security_group.id]
  db_subnet_group_name    = aws_db_subnet_group.default.name
  allow_major_version_upgrade = true
  auto_minor_version_upgrade = true
  publicly_accessible     = false

  tags = {
    Name = "PostgreSQLDBInstance"
  }
}

resource "aws_db_subnet_group" "default" {
  name       = "default-subnet-group"
  subnet_ids = [aws_subnet.custom_subnet.id]

  tags = {
    Name = "DefaultSubnetGroup"
  }
}
```

This Terraform configuration creates a VPC, a subnet within that VPC, a security group to control access to the PostgreSQL database, and the PostgreSQL database instance itself. The database instance is configured to allow major version upgrades, automatically perform minor version upgrades, and is not publicly accessible.

