This Terraform program sets up an AWS Lightsail environment with access to an S3 bucket. It creates an IAM role specifically for Lightsail to access the S3 bucket, attaches a policy to this role, and configures the S3 bucket policy to allow access from the Lightsail IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lightsail_bucket_access_role" {
  name = "lightsail-bucket-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_bucket_access_policy" {
  name        = "lightsail-bucket-access-policy"
  description = "Policy allowing Lightsail to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_bucket_access_policy" {
  policy_arn = aws_iam_policy.lightsail_bucket_access_policy.arn
  role       = aws_iam_role.lightsail_bucket_access_role.name
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket"
}

resource "aws_s3_bucket_policy" "bucket_policy_for_lightsail" {
  bucket = aws_s3_bucket.example_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_role.lightsail_bucket_access_role.arn
        }
        Resource = "arn:aws:s3:::example-bucket/*"
      }
    ]
  })
}
```

This Terraform configuration ensures that the AWS Lightsail service has the necessary permissions to access the specified S3 bucket. The IAM role and policy are created, and the S3 bucket policy is configured to allow access from the Lightsail IAM role.

