### Description
This Terraform program sets up an AWS Lightsail Content Delivery Network (CDN) distribution with an S3 bucket as the origin. It includes creating an S3 bucket, an IAM role with necessary permissions, and attaching the policy to the role. Finally, it creates the Lightsail distribution using the S3 bucket as the origin and the IAM role for access.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "lightsail_origin_bucket" {
  bucket = "my-lightsail-origin-bucket"
  acl    = "private"
}

resource "aws_iam_role" "lightsail_distribution_role" {
  name = "lightsail-distribution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_distribution_policy" {
  name        = "lightsail-distribution-policy"
  description = "Policy for Lightsail distribution to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.lightsail_origin_bucket.arn}",
          "${aws_s3_bucket.lightsail_origin_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_policy_to_role" {
  policy_arn = aws_iam_policy.lightsail_distribution_policy.arn
  role       = aws_iam_role.lightsail_distribution_role.name
}

resource "aws_lightsail_distribution" "lightsail_content_delivery_network" {
  name       = "my-lightsail-cdn"
  bundle_id  = "small_1_0"
  is_enabled = true

  origin {
    name       = aws_s3_bucket.lightsail_origin_bucket.bucket
    region_name = "us-east-1"
  }

  default_cache_behavior {
    behavior = "cache"
  }

  cache_behavior {
    path     = "/*"
    behavior = "cache"
  }
}
```

This Terraform configuration ensures that the S3 bucket is created, an IAM role with the necessary permissions is set up, and the Lightsail distribution is configured to use the S3 bucket as its origin. The IAM role is assumed by Lightsail, and the policy grants the required permissions for accessing the S3 bucket.

