### Description
This Terraform program creates an S3 bucket for long-term data storage and enables versioning on it to support backups. Additionally, it creates an IAM role and policy for S3 backup operations and attaches the policy to the role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "long_term_data_storage" {
  bucket = "long-term-data-storage-bucket"
  acl    = "private"
  tags = {
    Name        = "LongTermDataStorage"
    Environment = "production"
  }
}

resource "aws_s3_bucket_versioning" "long_term_data_storage_versioning" {
  bucket = aws_s3_bucket.long_term_data_storage.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "s3_backup_role" {
  name = "S3BackupRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_backup_policy" {
  name        = "S3BackupPolicy"
  description = "Policy for S3 backup operations"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.long_term_data_storage.arn}/*",
          aws_s3_bucket.long_term_data_storage.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_backup_policy_to_role" {
  policy_arn = aws_iam_policy.s3_backup_policy.arn
  role       = aws_iam_role.s3_backup_role.name
}
```

This Terraform configuration sets up an S3 bucket for long-term data storage with versioning enabled. It also creates an IAM role and policy specifically for S3 backup operations and attaches the policy to the role. The IAM role assumes that EC2 instances might need these permissions, but you can adjust the `assume_role_policy` as needed for your specific use case.

