### Description
This Terraform program creates an S3 Glacier vault and configures AWS Data Lifecycle Manager (DLM) to manage its lifecycle. It includes the creation of an IAM role and policy necessary for DLM to access and manage the S3 Glacier vault.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_glacier_vault" "s3_glacier_vault" {
  name = "my-glacier-vault"
}

resource "aws_iam_role" "data_lifecycle_manager_role" {
  name = "dlm-glacier-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "data_lifecycle_manager_policy" {
  name        = "dlm-glacier-policy"
  description = "Policy for AWS Data Lifecycle Manager to manage S3 Glacier vault"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateJob",
          "glacier:GetJobOutput",
          "glacier:DescribeVault",
          "glacier:ListJobs"
        ]
        Effect   = "Allow"
        Resource = aws_s3_glacier_vault.s3_glacier_vault.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_data_lifecycle_manager_policy" {
  policy_arn = aws_iam_policy.data_lifecycle_manager_policy.arn
  role       = aws_iam_role.data_lifecycle_manager_role.name
}

resource "aws_dlm_lifecycle_policy" "dlm_lifecycle_policy" {
  description          = "Lifecycle policy for S3 Glacier vault"
  execution_role_arn   = aws_iam_role.data_lifecycle_manager_role.arn
  state                = "ENABLED"

  policy_details {
    policy_type = "SCHEDULED"

    resource_types = [
      "VOLUME"
    ]

    schedule {
      name     = "weekly-snapshot"
      copy_tags = true

      create_rule {
        interval      = 7
        interval_unit = "DAY"
        times         = ["23:45"]
      }

      retain_rule {
        count = 1
      }
    }
  }
}
```

This Terraform configuration sets up an S3 Glacier vault, an IAM role with the necessary permissions, and a DLM lifecycle policy to manage the vault's lifecycle. The IAM role and policy ensure that DLM has the required permissions to interact with the S3 Glacier vault.

