}

resource "aws_iam_role" "s3_glacier_vault_notification_role" {
  name = "s3-glacier-vault-notification-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_glacier_vault_notification_policy" {
  name        = "s3-glacier-vault-notification-policy"
  description = "Policy allowing S3 Glacier to publish to the SNS topic"

