  name = "my-glacier-vault"
}

resource "aws_sns_topic" "sns_topic" {
  name = "archive-retrieval-notifications"
}

resource "aws_sns_topic_subscription" "sns_topic_subscription" {
  topic_arn = aws_sns_topic.sns_topic.arn
  protocol  = "email"
  endpoint  = "example@example.com"
}

resource "aws_s3_bucket_notification" "s3_bucket_notification" {
  bucket = aws_s3_glacier_vault.s3_glacier_vault.name

  topic {
    topic_arn = aws_sns_topic.sns_topic.arn
    events    = ["s3:GlacierRetrievalCompleted"]
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Glacier Vault**: An S3 Glacier vault named `my-glacier-vault` is created.
3. **SNS Topic**: An SNS topic named `archive-retrieval-notifications` is created.
4. **SNS Topic Subscription**: The SNS topic is subscribed to receive email notifications at `example@example.com`.
5. **S3 Bucket Notification**: The S3 Glacier vault is configured to send notifications to the SNS topic when an archive retrieval is completed.

This configuration ensures that when an archive retrieval is completed in the S3 Glacier vault, a notification is sent to the specified SNS topic, which can then be delivered to the subscribed endpoint.

