### Description
This Terraform program creates an Application Load Balancer named `test-lb-tf` in the AWS region `us-west-2`. The load balancer is configured with two subnets in different availability zones for high availability. A security group is also created to control inbound traffic to the load balancer. The load balancer is not internal and has deletion protection enabled.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "test_lb_sg" {
  name        = "test-lb-sg"
  description = "Security group for test-lb-tf"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "test_lb_tf" {
  name               = "test-lb-tf"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.test_lb_sg.id]
  enable_deletion_protection = true

  subnet_mapping {
    subnet_id = aws_subnet.subnet_1.id
  }

  subnet_mapping {
    subnet_id = aws_subnet.subnet_2.id
  }
}
```

This Terraform configuration sets up the necessary resources to create an Application Load Balancer with the specified requirements. The VPC, subnets, security group, and load balancer are all defined and interconnected as per the dependencies inferred from the prompt.

