LLM Output #0:
### Description
This Terraform program creates an internal-facing Application Load Balancer (ALB) with an HTTP listener and a target group. The load balancer is configured to use private IP addresses, ensuring that it is only accessible within the specified VPC and subnets. The program also includes a listener rule to forward incoming traffic to the target group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  count             = 2
  vpc_id            = aws_vpc.example.id
  cidr_block        = cidrsubnet(aws_vpc.example.cidr_block, 8, count.index)
  availability_zone = element(["us-west-2a", "us-west-2b"], count.index)
}

resource "aws_lb" "internal_load_balancer" {
  name               = "internal-alb"
  internal           = true
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = aws_subnet.example[0].id
  }

  subnet_mapping {
    subnet_id = aws_subnet.example[1].id
  }
}

resource "aws_lb_target_group" "target_group_web" {
  name     = "web-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.example.id
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.internal_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group_web.arn
  }
}

resource "aws_lb_listener_rule" "rule_forward_to_target_group" {
  listener_arn = aws_lb_listener.listener_http.arn
  priority     = 100

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group_web.arn
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnets**: A VPC with a CIDR block of `10.0.0.0/16` is created, along with two subnets in different availability zones (`us-west-2a` and `us-west-2b`).
- **Load Balancer**: An internal-facing Application Load Balancer is created and associated with the two subnets.
- **Target Group**: A target group is defined to handle HTTP traffic on port 80.
- **Listener**: An HTTP listener is added to the load balancer, which forwards traffic to the target group.
- **Listener Rule**: A listener rule is created to forward traffic to the target group based on the host header `example.com`.

