### Description
This Terraform program creates an Application Load Balancer (ALB) with a fixed-response action. The ALB listens for HTTP traffic on port 80 and returns a fixed response when a request matches a specific rule. Additionally, an IAM role and policy are created for the load balancer, although they are not strictly necessary for the basic functionality of the ALB.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with a valid subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with a valid security group ID
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, World!"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "rule_fixed_response" {
  listener_arn = aws_lb_listener.listener_http.arn
  priority     = 1

  action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed Response Rule Matched"
      status_code  = "200"
    }
  }

  condition {
    field  = "path-pattern"
    values = ["/fixed"]
  }
}

resource "aws_iam_role" "lb_role" {
  name = "my-alb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lb_policy" {
  name        = "my-alb-policy"
  description = "Policy for the load balancer"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "elasticloadbalancing:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lb_policy" {
  policy_arn = aws_iam_policy.lb_policy.arn
  role       = aws_iam_role.lb_role.name
}
```

### Notes
- Replace `"subnet-0123456789abcdef0"` and `"sg-0123456789abcdef0"` with valid subnet and security group IDs from your AWS account.
- The IAM role and policy are included for completeness, but they are not strictly necessary for the basic functionality of the ALB.

