### Description
This Terraform program sets up an Application Load Balancer (ALB) with a listener and a listener rule that uses Cognito authentication. The program includes the necessary Cognito user pool and client, as well as an IAM role and policy to allow the load balancer to authenticate with Cognito.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "lb" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"
  }

  security_groups = ["sg-0123456789abcdef0"]
}

resource "aws_lb_listener" "lb_listener" {
  load_balancer_arn = aws_lb.lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Default response"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "lb_listener_rule" {
  listener_arn = aws_lb_listener.lb_listener.arn
  priority     = 1

  action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.cognito_user_pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.cognito_user_pool_client.id
      user_pool_domain    = "mydomain.auth.us-west-2.amazoncognito.com"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}

resource "aws_cognito_user_pool" "cognito_user_pool" {
  name = "my-user-pool"

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  password_policy {
    minimum_length                = 8
    require_lowercase             = true
    require_numbers               = true
    require_symbols               = true
    require_uppercase             = true
    temporary_password_validity_days = 7
  }
}

resource "aws_cognito_user_pool_client" "cognito_user_pool_client" {
  name            = "my-app-client"
  user_pool_id    = aws_cognito_user_pool.cognito_user_pool.id
  generate_secret = true
}

resource "aws_iam_role" "lb_auth_role" {
  name = "lb-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lb_auth_policy" {
  name        = "lb-auth-policy"
  description = "Policy for load balancer to authenticate with Cognito"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "cognito-idp:DescribeUserPoolClient",
          "cognito-idp:ListUserPoolClients"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lb_auth_policy_attachment" {
  policy_arn = aws_iam_policy.lb_auth_policy.arn
  role       = aws_iam_role.lb_auth_role.name
}
```

This Terraform configuration sets up an ALB with a listener and a listener rule that uses Cognito authentication. It includes the necessary Cognito user pool and client, as well as an IAM role and policy to allow the load balancer to authenticate with Cognito. The configuration is designed to be deployable with Terraform version 1.9.8 and the AWS provider version 5.75.

