Below is a complete Terraform HCL program that creates an Application Load Balancer (ALB) with an Authenticate-OIDC action. The program includes the necessary resources and dependencies as inferred from the prompt.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "lb" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"
  }

  security_groups = ["sg-0123456789abcdef0"]
}

resource "aws_lb_listener" "lb_listener" {
  load_balancer_arn = aws_lb.lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Fixed response content"
      status_code  = "200"
    }
  }
}

resource "aws_lb_target_group" "lb_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener_rule" "lb_listener_rule" {
  listener_arn = aws_lb_listener.lb_listener.arn
  priority     = 100

  action {
    type             = "authenticate-oidc"
    authenticate_oidc {
      authorization_endpoint = "https://example.com/auth"
      client_id              = "client-id"
      client_secret          = "client-secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/token"
      user_info_endpoint     = "https://example.com/userinfo"
      session_cookie_name    = "AWSELBAuthSessionCookie"
      scope                  = "openid email"
      on_unauthenticated_request = "authenticate"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}

resource "aws_iam_role" "oidc_auth_role" {
  name = "oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = "account-id:pool-id"
          }
          NumericLessThan = {
            "cognito-identity.amazonaws.com:amr:0" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "oidc_auth_policy" {
  name        = "oidc-auth-policy"
  description = "Policy for OIDC authentication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_oidc_auth_policy" {
  policy_arn = aws_iam_policy.oidc_auth_policy.arn
  role       = aws_iam_role.oidc_auth_role.name
}
```

This Terraform configuration sets up an Application Load Balancer with an Authenticate-OIDC action. It includes the necessary IAM role and policy for OIDC authentication. The load balancer, listener, listener rule, and target group are all configured to work together to handle incoming HTTP requests and authenticate users using OIDC.

