### Description
This Terraform program creates an Application Load Balancer (ALB) with an IP target group. The ALB listens on port 80 and forwards traffic to the IP target group. The program includes the necessary resources and configurations to ensure the load balancer and target group are properly set up in a VPC and subnet.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "example" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "example" {
  vpc_id            = aws_vpc.example.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_security_group" "example" {
  vpc_id = aws_vpc.example.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "load_balancer" {
  name               = "example-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.example.id]
  subnets            = [aws_subnet.example.id]

  access_logs {
    bucket = "my-load-balancer-logs"
    prefix = "alb-logs/"
  }
}

resource "aws_lb_target_group" "ip_target_group" {
  name        = "example-ip-target-group"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.example.id
  ip_address_type = "ipv4"

  health_check {
    enabled             = true
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
    path                = "/"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.ip_target_group.arn
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC and Subnet**: A VPC and a subnet are created within the VPC.
- **Security Group**: A security group is created to allow HTTP traffic on port 80.
- **Load Balancer**: An Application Load Balancer is created and associated with the security group and subnet.
- **Target Group**: An IP target group is created and associated with the VPC.
- **Listener**: A listener is created on port 80 to forward traffic to the IP target group.

