LLM Output #0:
Below is a complete Terraform HCL program that creates an Application Load Balancer (ALB) with a Lambda target group. The program includes the necessary IAM roles and policies for the Lambda function.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"
  }

  security_groups = ["sg-0123456789abcdef0"]
}

resource "aws_lb_target_group" "lambda_target_group" {
  name        = "my-lambda-target-group"
  port        = 443
  protocol    = "HTTPS"
  vpc_id      = "vpc-0123456789abcdef0"
  target_type = "lambda"
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_target_group.arn
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda-policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lambda_policy" {
  policy_arn = aws_iam_policy.lambda_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "my-lambda-function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "function.zip"
}

resource "aws_lb_target_group_attachment" "lambda_target_group_attachment" {
  target_group_arn = aws_lb_target_group.lambda_target_group.arn
  target_id        = aws_lambda_function.lambda_function.arn
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured with the region `us-west-2`.
2. **Load Balancer**: An Application Load Balancer (`aws_lb`) is created with a single subnet mapping and security group.
3. **Lambda Target Group**: A target group for Lambda functions (`aws_lb_target_group`) is created with the target type set to `lambda`.
4. **Listener**: A listener (`aws_lb_listener`) is created for the load balancer to forward traffic to the Lambda target group.
5. **IAM Role and Policy**: An IAM role (`aws_iam_role`) and policy (`aws_iam_policy`) are created for the Lambda function. The policy allows the Lambda function to write logs to CloudWatch.
6. **Lambda Function**: A Lambda function (`aws_lambda_function`) is created with the specified role, handler, runtime, and filename.
7. **Target Group Attachment**: The Lambda function is attached to the target group (`aws_lb_target_group_attachment`).

This configuration ensures that the ALB is correctly set up to route traffic to the Lambda function.

