### Description
This Terraform program creates an Application Load Balancer (ALB) with a target group and attaches a listener to the ALB that forwards traffic to the target group. The ALB is configured to handle HTTP traffic on port 80. The target group is set up to balance traffic across EC2 instances running on port 80.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-alb"
  internal           = false
  load_balancer_type = "application"

  subnet_mapping {
    subnet_id = "subnet-0123456789abcdef0"  # Replace with your subnet ID
  }

  security_groups = ["sg-0123456789abcdef0"]  # Replace with your security group ID

  tags = {
    Name = "MyALB"
  }
}

resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-0123456789abcdef0"  # Replace with your VPC ID

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "MyTargetGroup"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}
```

### Notes
- Replace the placeholder subnet IDs, security group IDs, and VPC IDs with actual values from your AWS account.
- Ensure that the security group associated with the ALB allows inbound traffic on port 80.
- This configuration assumes that you have already created the necessary subnets and security groups in your AWS account.

