### Description
This Terraform program creates an AWS EFS (Elastic File System) with automatic backups enabled using AWS Backup. The program includes the following resources:

1. **aws_efs_file_system**: Creates an EFS file system.
2. **aws_backup_vault**: Creates a backup vault where backups will be stored.
3. **aws_backup_plan**: Defines a backup plan that specifies how often and how long backups should be retained.
4. **aws_backup_selection**: Selects the EFS file system to be backed up according to the defined backup plan.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-file-system"
  encrypted      = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = "MyEFSFileSystem"
  }
}

resource "aws_backup_vault" "backup_vault" {
  name = "efs-backup-vault"

  tags = {
    Name = "MyEFSSnapshotVault"
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = "efs-backup-plan"

  rule {
    rule_name         = "DailyBackup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"  # Daily at midnight UTC
    start_window      = 60                    # 1 hour
    completion_window = 120                   # 2 hours
  }

  tags = {
    Name = "MyEFSSnapshotPlan"
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = "arn:aws:iam::123456789012:role/service-role/AWSBackupDefaultServiceRole"  # Replace with your IAM role ARN
  plan_id      = aws_backup_plan.backup_plan.id
  name         = "efs-backup-selection"

  resources = [
    aws_efs_file_system.efs_file_system.arn
  ]

  tags = {
    Name = "MyEFSSnapshotSelection"
  }
}
```

### Notes
- Ensure that the AWS Backup service is enabled in your AWS account.
- Replace the `iam_role_arn` in the `aws_backup_selection` resource with the ARN of an IAM role that has the necessary permissions to perform backups.
- The `region` in the provider configuration should be set to your desired AWS region.

