This Terraform program creates a Virtual Private Cloud (VPC) with a CIDR block of `10.0.0.0/16` and an Internet Gateway in the AWS `us-east-2` region. Both the VPC and the Internet Gateway are tagged with the names "vpc" and "ig", respectively. The Internet Gateway is attached to the VPC after the VPC is created.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "vpc"
  }
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
  tags = {
    Name = "ig"
  }
}
```

This configuration ensures that the VPC is created first, and then the Internet Gateway is attached to it. All necessary attributes and tags are specified as per the requirements.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 4.16"
    }
  }

  required_version = ">= 1.2.0"
}
# Define the provider block for AWS
provider "aws" {
  region = "us-east-2" # Set your desired AWS region
}

resource "aws_vpc" "_" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = merge({
    "Name" = "vpc"
  })
}

resource "aws_internet_gateway" "_" {
  vpc_id = aws_vpc._.id
  tags = merge({
    "Name" = "ig"
  })
}

