### Description
This Terraform program creates an egress-only internet gateway named "pike" associated with a specified VPC, allowing IPv6-enabled instances to connect to the internet without allowing inbound internet traffic. The egress-only internet gateway is tagged with "permissions". The program includes a VPC resource and ensures proper dependencies between the resources.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_vpc" "vpc_for_egress" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "VPC for Egress"
  }
}

resource "aws_egress_only_internet_gateway" "egress_only_internet_gateway_pike" {
  vpc_id = aws_vpc.vpc_for_egress.id

  tags = {
    Name        = "pike"
    permissions = "true"
  }
}
```

